// 🤲 دعاء اليوم — إضافة موسّعة (قرآني + أذكار + أدعية نبوية)
const DUAS_EXTRA = [{"id":"q_2_128","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةًۭ مُّسْلِمَةًۭ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ","transliteration":"","translation_es":"“¡Señor nuestro! Haz que nosotros nos entreguemos a Tu voluntad, y que nuestra descendencia también lo haga [como una nación de musulmanes]. Enséñanos nuestros ritos para la pe-","translation_ar":"ربنا وٱجعلنا مسلمين لك ومن ذريتنآ أمة مسلمة لك وأرنا مناسكنا وتب علينآ  إنك أنت ٱلتواب ٱلرحيم","translation_en":"Our Lord, and make us Muslims [in submission] to You and from our descendants a Muslim nation [in submission] to You. And show us our rites and accept our repentance. Indeed, You are the Accepting of repentance, the Merciful.","source":"Al-Baqara 2:128"},{"id":"q_2_129","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","transliteration":"","translation_es":"“¡Señor nuestro! Haz surgir de entre nuestra descendencia un Mensajero que les recite Tus palabras y les enseñe el Libro y la sabiduría, y los purifique. Tú eres el Poderoso, el Sabio”.","translation_ar":"ربنا وٱبعث فيهم رسولا منهم يتلوا عليهم ءايتك ويعلمهم ٱلكتب وٱلحكمة ويزكيهم  إنك أنت ٱلعزيز ٱلحكيم","translation_en":"Our Lord, and send among them a messenger from themselves who will recite to them Your verses and teach them the Book and wisdom and purify them. Indeed, You are the Exalted in Might, the Wise.\"","source":"Al-Baqara 2:129"},{"id":"q_3_8","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ","transliteration":"","translation_es":"¡Señor nuestro! No permitas que nuestros corazones se desvíen después de habernos guiado. Concédenos Tu misericordia, Tú eres el Dadivoso.","translation_ar":"ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة  إنك أنت ٱلوهاب","translation_en":"[Who say], \"Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.","source":"Aal-i-Imraan 3:8"},{"id":"q_3_9","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ","transliteration":"","translation_es":"¡Señor nuestro! [Atestiguamos que] Tú reunirás a los seres humanos para un Día ineludible. Dios no falta jamás a Su promesa”.","translation_ar":"ربنآ إنك جامع ٱلناس ليوم لا ريب فيه  إن ٱلله لا يخلف ٱلميعاد","translation_en":"Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise.\"","source":"Aal-i-Imraan 3:9"},{"id":"q_3_53","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ","transliteration":"","translation_es":"¡Señor nuestro! Creemos en lo que has revelado y seguimos a Tu Profeta. Cuéntanos entre los que dan testimonio de fe”.","translation_ar":"ربنآ ءامنا بمآ أنزلت وٱتبعنا ٱلرسول فٱكتبنا مع ٱلشهدين","translation_en":"Our Lord, we have believed in what You revealed and have followed the messenger Jesus, so register us among the witnesses [to truth].\"","source":"Aal-i-Imraan 3:53"},{"id":"q_3_192","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ","transliteration":"","translation_es":"¡Señor nuestro! A quien condenes al Fuego lo habrás deshonrado, porque los opresores no tendrán quién los auxilie.","translation_ar":"ربنآ إنك من تدخل ٱلنار فقد أخزيته  وما للظلمين من أنصار","translation_en":"Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers.","source":"Aal-i-Imraan 3:192"},{"id":"q_3_193","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ","transliteration":"","translation_es":"¡Señor nuestro! Hemos oído a quien convocaba a la fe, diciendo: ‘Crean en su Señor’, y creímos. ¡Señor nuestro! Perdona nuestros pecados, borra nuestras malas acciones y, al morir, reúnenos con los piadosos.","translation_ar":"ربنآ إننا سمعنا مناديا ينادى للإيمن أن ءامنوا بربكم فٔامنا  ربنا فٱغفر لنا ذنوبنا وكفر عنا سئاتنا وتوفنا مع ٱلأبرار","translation_en":"Our Lord, indeed we have heard a caller calling to faith, [saying], 'Believe in your Lord,' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous.","source":"Aal-i-Imraan 3:193"},{"id":"q_3_194","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ","transliteration":"","translation_es":"¡Señor nuestro! Concédenos lo que has prometido a través de Tus Mensajeros y no nos humilles el Día de la Resurrección. Tú no faltas a Tu promesa”.","translation_ar":"ربنا وءاتنا ما وعدتنا على رسلك ولا تخزنا يوم ٱلقيمة  إنك لا تخلف ٱلميعاد","translation_en":"Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.\"","source":"Aal-i-Imraan 3:194"},{"id":"q_7_122","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ مُوسَىٰ وَهَٰرُونَ","transliteration":"","translation_es":"el Señor de Moisés y de Aarón”.","translation_ar":"رب موسى وهرون","translation_en":"The Lord of Moses and Aaron.\"","source":"Al-A'raaf 7:122"},{"id":"q_14_36","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًۭا مِّنَ ٱلنَّاسِ ۖ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى ۖ وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌۭ رَّحِيمٌۭ","transliteration":"","translation_es":"¡Oh, Señor mío! La adoración a los ídolos ha extraviado a muchas personas. Todo aquel que me siga [en la fe monoteísta] será de los míos, pero quien me desobedezca [rechazando el Mensaje]… Tú eres Absolvedor, Misericordioso.","translation_ar":"رب إنهن أضللن كثيرا من ٱلناس  فمن تبعنى فإنه منى  ومن عصانى فإنك غفور رحيم","translation_en":"My Lord, indeed they have led astray many among the people. So whoever follows me - then he is of me; and whoever disobeys me - indeed, You are [yet] Forgiving and Merciful.","source":"Ibrahim 14:36"},{"id":"q_14_37","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةًۭ مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ","transliteration":"","translation_es":"¡Oh, Señor nuestro! He establecido parte de mi descendencia en un valle árido de poca vegetación junto a Tu Casa Sagrada, para que, ¡oh, Señor nuestro!, cumplan con la oración. Infunde en los corazones de la gente amor por mi descendencia, y provéelos de todo alimento para que sean agradecidos.","translation_ar":"ربنآ إنىٓ أسكنت من ذريتى بواد غير ذى زرع عند بيتك ٱلمحرم ربنا ليقيموا ٱلصلوة فٱجعل أفٔدة من ٱلناس تهوىٓ إليهم وٱرزقهم من ٱلثمرت لعلهم يشكرون","translation_en":"Our Lord, I have settled some of my descendants in an uncultivated valley near Your sacred House, our Lord, that they may establish prayer. So make hearts among the people incline toward them and provide for them from the fruits that they might be grateful.","source":"Ibrahim 14:37"},{"id":"q_14_38","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍۢ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ","transliteration":"","translation_es":"¡Oh, Señor nuestro! Tú bien sabes lo que ocultamos y lo que manifestamos, y no hay nada en la Tierra ni en el cielo que pueda esconderse de Dios.","translation_ar":"ربنآ إنك تعلم ما نخفى وما نعلن  وما يخفى على ٱلله من شىء فى ٱلأرض ولا فى ٱلسمآء","translation_en":"Our Lord, indeed You know what we conceal and what we declare, and nothing is hidden from Allah on the earth or in the heaven.","source":"Ibrahim 14:38"},{"id":"q_14_40","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ","transliteration":"","translation_es":"¡Oh, Señor mío! Haz que tanto mis descendientes como yo seamos fervientes practicantes de la oración. ¡Oh, Señor nuestro! Concédeme esta súplica.","translation_ar":"رب ٱجعلنى مقيم ٱلصلوة ومن ذريتى  ربنا وتقبل دعآء","translation_en":"My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.","source":"Ibrahim 14:40"},{"id":"q_14_41","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ","transliteration":"","translation_es":"¡Oh, Señor nuestro! Perdóname, así como a mis padres y a todos los creyentes el Día que se celebre el Juicio [Final]”.","translation_ar":"ربنا ٱغفر لى ولولدى وللمؤمنين يوم يقوم ٱلحساب","translation_en":"Our Lord, forgive me and my parents and the believers the Day the account is established.\"","source":"Ibrahim 14:41"},{"id":"q_19_65","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ ۚ هَلْ تَعْلَمُ لَهُۥ سَمِيًّۭا","transliteration":"","translation_es":"Es el Señor de los cielos, de la Tierra y de cuanto hay entre ambos. Adóralo y persevera en Su adoración. ¿Conoces a alguien similar a Él?”","translation_ar":"رب ٱلسموت وٱلأرض وما بينهما فٱعبده وٱصطبر لعبدته  هل تعلم له سميا","translation_en":"Lord of the heavens and the earth and whatever is between them - so worship Him and have patience for His worship. Do you know of any similarity to Him?\"","source":"Maryam 19:65"},{"id":"q_23_94","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّٰلِمِينَ","transliteration":"","translation_es":"Señor, no me pongas entre los injustos”.","translation_ar":"رب فلا تجعلنى فى ٱلقوم ٱلظلمين","translation_en":"My Lord, then do not place me among the wrongdoing people.\"","source":"Al-Muminoon 23:94"},{"id":"q_23_107","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ","transliteration":"","translation_es":"¡Oh, Señor nuestro! Sácanos de él [y retórnanos a la vida], y si reincidimos [en la incredulidad] entonces sí seremos injustos”15.","translation_ar":"ربنآ أخرجنا منها فإن عدنا فإنا ظلمون","translation_en":"Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers.\"","source":"Al-Muminoon 23:107"},{"id":"q_26_48","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ مُوسَىٰ وَهَٰرُونَ","transliteration":"","translation_es":"el Señor de Moisés y de Aarón”.","translation_ar":"رب موسى وهرون","translation_en":"The Lord of Moses and Aaron.\"","source":"Ash-Shu'araa 26:48"},{"id":"q_26_83","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ هَبْ لِى حُكْمًۭا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ","transliteration":"","translation_es":"¡Oh, Señor mío! Concédeme sabiduría y estar entre los justos.","translation_ar":"رب هب لى حكما وألحقنى بٱلصلحين","translation_en":"[And he said], \"My Lord, grant me authority and join me with the righteous.","source":"Ash-Shu'araa 26:83"},{"id":"q_26_169","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ نَجِّنِى وَأَهْلِى مِمَّا يَعْمَلُونَ","transliteration":"","translation_es":"¡Oh, Señor mío! Protégenos, a mi familia y a mí, de lo que ellos hacen”.","translation_ar":"رب نجنى وأهلى مما يعملون","translation_en":"My Lord, save me and my family from [the consequence of] what they do.\"","source":"Ash-Shu'araa 26:169"},{"id":"q_33_68","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًۭا كَبِيرًۭا","transliteration":"","translation_es":"¡Señor nuestro! Duplícales a ellos el castigo y maldícelos completamente”.","translation_ar":"ربنآ ءاتهم ضعفين من ٱلعذاب وٱلعنهم لعنا كبيرا","translation_en":"Our Lord, give them double the punishment and curse them with a great curse.\"","source":"Al-Ahzaab 33:68"},{"id":"q_37_5","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَٰرِقِ","transliteration":"","translation_es":"el Señor de los cielos, de la Tierra, de todo cuanto existe entre ellos; el Señor de los amaneceres.","translation_ar":"رب ٱلسموت وٱلأرض وما بينهما ورب ٱلمشرق","translation_en":"Lord of the heavens and the earth and that between them and Lord of the sunrises.","source":"As-Saaffaat 37:5"},{"id":"q_37_100","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ","transliteration":"","translation_es":"¡Oh, Señor mío! Concédeme un hijo justo”.","translation_ar":"رب هب لى من ٱلصلحين","translation_en":"My Lord, grant me [a child] from among the righteous.\"","source":"As-Saaffaat 37:100"},{"id":"q_38_66","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ","transliteration":"","translation_es":"Señor de los cielos, de la Tierra, y de todo cuanto existe entre ellos, el Poderoso, el Remisorio”.","translation_ar":"رب ٱلسموت وٱلأرض وما بينهما ٱلعزيز ٱلغفر","translation_en":"Lord of the heavens and the earth and whatever is between them, the Exalted in Might, the Perpetual Forgiver.\"","source":"Saad 38:66"},{"id":"q_40_8","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","transliteration":"","translation_es":"¡Señor nuestro! Introdúcelos en los Jardines del Edén que les prometiste, junto a sus padres, esposas y descendientes que fueron piadosos y creyentes. Tú eres el Poderoso, el Sabio.","translation_ar":"ربنا وأدخلهم جنت عدن ٱلتى وعدتهم ومن صلح من ءابآئهم وأزوجهم وذريتهم  إنك أنت ٱلعزيز ٱلحكيم","translation_en":"Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.","source":"Ghafir 40:8"},{"id":"q_44_7","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ","transliteration":"","translation_es":"Señor de los cielos y de la Tierra, y de lo que existe entre ambos. ¿Acaso no tienen certeza de eso?","translation_ar":"رب ٱلسموت وٱلأرض وما بينهمآ  إن كنتم موقنين","translation_en":"Lord of the heavens and the earth and that between them, if you would be certain.","source":"Ad-Dukhaan 44:7"},{"id":"q_44_12","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ","transliteration":"","translation_es":"[Dirán los que se negaron a creer:] “¡Oh, Señor nuestro! Aparta de nosotros el castigo, somos creyentes”.","translation_ar":"ربنا ٱكشف عنا ٱلعذاب إنا مؤمنون","translation_en":"[They will say], \"Our Lord, remove from us the torment; indeed, we are believers.\"","source":"Ad-Dukhaan 44:12"},{"id":"q_55_17","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ","transliteration":"","translation_es":"El Señor de los dos nacientes y los dos ponientes.","translation_ar":"رب ٱلمشرقين ورب ٱلمغربين","translation_en":"[He is] Lord of the two sunrises and Lord of the two sunsets.","source":"Ar-Rahmaan 55:17"},{"id":"q_60_5","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةًۭ لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","transliteration":"","translation_es":"¡Señor nuestro! No permitas que los que se han negado a creer nos persigan, ni hagas de nosotros una causa por la cual se alejen [del Islam]. Perdónanos, ¡oh, Señor nuestro! Tú eres el Poderoso, el Sabio”.","translation_ar":"ربنا لا تجعلنا فتنة للذين كفروا وٱغفر لنا ربنآ  إنك أنت ٱلعزيز ٱلحكيم","translation_en":"Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise.\"","source":"Al-Mumtahana 60:5"},{"id":"q_71_28","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًۭا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًۢا","transliteration":"","translation_es":"¡Señor mío! Perdóname y perdona a mis padres, a todo aquel que ingrese a mi casa como creyente, y a todos los hombres y mujeres que crean en Ti. Pero a los injustos opresores, acreciéntales su perdición”.","translation_ar":"رب ٱغفر لى ولولدى ولمن دخل بيتى مؤمنا وللمؤمنين وٱلمؤمنت ولا تزد ٱلظلمين إلا تبارا","translation_en":"My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction.\"","source":"Nooh 71:28"},{"id":"q_73_9","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًۭا","transliteration":"","translation_es":"Él es el Señor del oriente y del occidente. No hay nada ni nadie con derecho a ser adorado salvo Él. Tómalo como tu protector.","translation_ar":"رب ٱلمشرق وٱلمغرب لآ إله إلا هو فٱتخذه وكيلا","translation_en":"[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs.","source":"Al-Muzzammil 73:9"},{"id":"q_78_37","title":"Súplica coránica","title_ar":"دعاء قرآني","title_en":"Quranic supplication","arabic":"رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًۭا","transliteration":"","translation_es":"El Señor de los cielos, de la Tierra y de lo que hay entre ellos, el Compasivo. Nadie puede hablar ante Él excepto con Su permiso.","translation_ar":"رب ٱلسموت وٱلأرض وما بينهما ٱلرحمن  لا يملكون منه خطابا","translation_en":"[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech.","source":"An-Naba 78:37"},{"id":"a_after_astaghfirullah","title":"Pedir perdón 3 veces","title_ar":"الاستغفار ثلاث مرات","title_en":"Seeking forgiveness 3 times","arabic":"أَسْتَغْفِرُ اللَّهَ • أَسْتَغْفِرُ اللَّهَ • أَسْتَغْفِرُ اللَّهَ","transliteration":"Astaghfirullah (×3)","translation_es":"Pido perdón a Allah.","translation_ar":"أستغفر الله.","translation_en":"I seek Allah's forgiveness.","source":"Muslim"},{"id":"a_after_salam","title":"Allahumma anta as-Salam","title_ar":"اللهم أنت السلام","title_en":"Allahumma anta as-Salam (O Allah, You are Peace)","arabic":"اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","transliteration":"Allahumma anta as-Salamu wa minka as-Salam, tabarakta ya dhal-jalali wal-ikram","translation_es":"Oh Allah, Tú eres la Paz y de Ti viene la paz. Bendito eres, oh Poseedor de Majestad y Honor.","translation_ar":"اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام.","translation_en":"O Allah, You are Peace and from You comes peace. Blessed are You, O Owner of Majesty and Honor.","source":"Muslim"},{"id":"a_after_subhanallah","title":"Tasbih después de oración","title_ar":"التسبيح بعد الصلاة","title_en":"Tasbih after prayer","arabic":"سُبْحَانَ اللَّهِ","transliteration":"Subhanallah","translation_es":"Glorificado sea Allah.","translation_ar":"سبحان الله.","translation_en":"Glory be to Allah.","source":"Muslim"},{"id":"a_after_alhamdulillah","title":"Tahmid","title_ar":"التحميد","title_en":"Tahmid (praising Allah)","arabic":"الْحَمْدُ لِلَّهِ","transliteration":"Alhamdulillah","translation_es":"Alabado sea Allah.","translation_ar":"الحمد لله.","translation_en":"All praise is for Allah.","source":"Muslim"},{"id":"a_after_allahuakbar","title":"Takbir","title_ar":"التكبير","title_en":"Takbir","arabic":"اللَّهُ أَكْبَرُ","transliteration":"Allahu Akbar","translation_es":"Allah es el más Grande.","translation_ar":"الله أكبر.","translation_en":"Allah is the Greatest.","source":"Muslim"},{"id":"a_after_la_ilaha","title":"Cierre del tasbih","title_ar":"خاتمة التسبيح","title_en":"Closing of the tasbih","arabic":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","transliteration":"La ilaha illa Allah wahdahu la sharika lah, lahu-l-mulku wa lahu-l-hamdu wa huwa 'ala kulli shay'in qadir","translation_es":"No hay divinidad sino Allah, Único, sin asociado. Suyo es el reino y la alabanza, y es Omnipotente sobre todo.","translation_ar":"لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.","translation_en":"There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He has power over all things.","source":"Muslim"},{"id":"a_after_ayatul_kursi","title":"Ayat al-Kursi","title_ar":"آية الكرسي","title_en":"Ayat al-Kursi","arabic":"اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ...","transliteration":"Allahu la ilaha illa Huwa, Al-Hayyul-Qayyum...","translation_es":"Allah, no hay más divinidad que Él, el Viviente, el Eterno...","translation_ar":"الله لا إله إلا هو الحي القيوم...","translation_en":"Allah — there is no god but He, the Ever-Living, the Sustainer of all...","source":"An-Nasa'i"},{"id":"a_after_three_quls","title":"Las tres Quls","title_ar":"المعوذات الثلاث","title_en":"The three Quls","arabic":"قُلْ هُوَ اللَّهُ أَحَدٌ • قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ • قُلْ أَعُوذُ بِرَبِّ النَّاسِ","transliteration":"Qul huwa Allahu ahad... Qul a'udhu...","translation_es":"Las tres últimas suras del Corán.","translation_ar":"السور الثلاث الأخيرة من القرآن.","translation_en":"The last three surahs of the Quran.","source":"Abu Dawud"},{"id":"a_enter_bathroom","title":"Al entrar al baño","title_ar":"عند دخول الخلاء","title_en":"Upon entering the bathroom","arabic":"بِسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","transliteration":"Bismillah, Allahumma inni a'udhu bika mina-l-khubuthi wa-l-khaba'ith","translation_es":"En el nombre de Allah. ¡Oh Allah! Me refugio en Ti de los demonios machos y hembras.","translation_ar":"بسم الله، اللهم إني أعوذ بك من الخبث والخبائث.","translation_en":"In the name of Allah. O Allah! I seek refuge in You from the male and female devils.","source":"Bukhari 142"},{"id":"a_exit_bathroom","title":"Al salir del baño","title_ar":"عند الخروج من الخلاء","title_en":"Upon leaving the bathroom","arabic":"غُفْرَانَكَ","transliteration":"Ghufranak","translation_es":"Tu perdón (¡oh Allah!).","translation_ar":"غفرانك.","translation_en":"Your forgiveness (O Allah!).","source":"Tirmidhi 7"},{"id":"a_exit_bathroom_long","title":"Súplica extendida al salir del baño","title_ar":"دعاء مطوّل عند الخروج من الخلاء","title_en":"Extended supplication upon leaving the bathroom","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الْأَذَى وَعَافَانِي","transliteration":"Al-hamdu lillahi-lladhi adhhaba 'anni-l-adha wa 'afani","translation_es":"Alabado sea Allah, Quien alejó de mí el daño y me dio salud.","translation_ar":"الحمد لله الذي أذهب عني الأذى وعافاني.","translation_en":"All praise is for Allah, Who removed harm from me and granted me health.","source":"Ibn Majah 301"},{"id":"a_after_wudu_bathroom","title":"Después del wudu (que suele seguir al baño)","title_ar":"بعد الوضوء (الذي يلي الخلاء غالباً)","title_en":"After wudu (which often follows the bathroom)","arabic":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ، وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ","transliteration":"Ashhadu an la ilaha illa Allah wahdahu la sharika lah, wa ashhadu anna Muhammadan 'abduhu wa rasuluh. Allahumma-j'alni mina-t-tawwabin, waj'alni mina-l-mutatahhirin","translation_es":"Atestiguo que no hay divinidad sino Allah, Único, sin asociados, y atestiguo que Muhammad es Su siervo y Mensajero. ¡Oh Allah! Hazme de los que se arrepienten y hazme de los que se purifican.","translation_ar":"أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمداً عبده ورسوله. اللهم اجعلني من التوابين، واجعلني من المتطهرين.","translation_en":"I bear witness that there is no god but Allah alone, without partner, and I bear witness that Muhammad is His servant and Messenger. O Allah! Make me among those who repent and make me among those who purify themselves.","source":"Muslim 234"},{"id":"a_karb_azim","title":"Súplica de la gran angustia","title_ar":"دعاء الكرب العظيم","title_en":"Supplication for great distress","arabic":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","transliteration":"La ilaha illa Allahu-l-'Azimu-l-Halim, la ilaha illa Allahu Rabbu-l-'arshi-l-'azim, la ilaha illa Allahu Rabbu-s-samawati wa Rabbu-l-ardi wa Rabbu-l-'arshi-l-karim","translation_es":"No hay divinidad sino Allah, el Grandioso, el Clemente. No hay divinidad sino Allah, Señor del Trono inmenso. No hay divinidad sino Allah, Señor de los cielos, Señor de la tierra y Señor del Trono generoso.","translation_ar":"لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم.","translation_en":"There is no god but Allah, the Magnificent, the Forbearing. There is no god but Allah, Lord of the mighty Throne. There is no god but Allah, Lord of the heavens, Lord of the earth and Lord of the noble Throne.","source":"Bukhari 6346"},{"id":"a_yunus_dua","title":"La súplica de Yunus (Jonás) عليه السلام","title_ar":"دعاء يونس عليه السلام","title_en":"The supplication of Yunus (Jonah) عليه السلام","arabic":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","transliteration":"La ilaha illa anta subhanaka inni kuntu mina-z-zalimin","translation_es":"No hay divinidad sino Tú, Glorificado seas. Ciertamente, he sido de los injustos.","translation_ar":"لا إله إلا أنت سبحانك إني كنت من الظالمين.","translation_en":"There is no god but You, glory be to You. Indeed, I have been among the wrongdoers.","source":"Tirmidhi 3505"},{"id":"a_hasbunallah","title":"Hasbunallahu wa ni'ma-l-Wakil","title_ar":"حسبنا الله ونعم الوكيل","title_en":"Hasbunallahu wa ni'ma-l-Wakil (Allah is sufficient for us)","arabic":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ","transliteration":"Hasbunallahu wa ni'ma-l-Wakil","translation_es":"Nos basta Allah y qué excelente Protector es.","translation_ar":"حسبنا الله ونعم الوكيل.","translation_en":"Allah is sufficient for us, and He is the best Disposer of affairs.","source":"Bukhari 4563"},{"id":"a_la_hawla","title":"La hawla wa la quwwata illa billah","title_ar":"لا حول ولا قوة إلا بالله","title_en":"La hawla wa la quwwata illa billah","arabic":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","transliteration":"La hawla wa la quwwata illa billah","translation_es":"No hay poder ni fuerza sino en Allah.","translation_ar":"لا حول ولا قوة إلا بالله.","translation_en":"There is no power nor might except with Allah.","source":"Bukhari 6384"},{"id":"a_debt_dua","title":"Súplica contra las deudas","title_ar":"دعاء قضاء الدَّين","title_en":"Supplication against debts","arabic":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","transliteration":"Allahumma-kfini bi-halalika 'an haramik, wa aghnini bi-fadlika 'amman siwak","translation_es":"¡Oh Allah! Bástame con lo que has hecho lícito y aléjame de lo que has prohibido, y enriquéceme con Tu favor y prescindéme de todo aparte de Ti.","translation_ar":"اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمن سواك.","translation_en":"O Allah! Suffice me with Your lawful provision against Your unlawful, and enrich me by Your bounty so I need none besides You.","source":"Tirmidhi 3563"},{"id":"a_hamm_wa_hazan","title":"Refugio de las 8 preocupaciones","title_ar":"الاستعاذة من ثمانية هموم","title_en":"Refuge from the 8 worries","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ","transliteration":"Allahumma inni a'udhu bika mina-l-hammi wa-l-hazan, wa a'udhu bika mina-l-'ajzi wa-l-kasal, wa a'udhu bika mina-l-jubni wa-l-bukhl, wa a'udhu bika min ghalabati-d-dayni wa qahri-r-rijal","translation_es":"¡Oh Allah! Me refugio en Ti de la preocupación y la tristeza, me refugio en Ti de la incapacidad y la pereza, me refugio en Ti de la cobardía y la avaricia, y me refugio en Ti de sentirme abrumado por deudas y de ser oprimido por hombres.","translation_ar":"اللهم إني أعوذ بك من الهم والحزن، وأعوذ بك من العجز والكسل، وأعوذ بك من الجبن والبخل، وأعوذ بك من غلبة الدين وقهر الرجال.","translation_en":"O Allah! I seek refuge in You from worry and grief, from incapacity and laziness, from cowardice and miserliness, and from being overwhelmed by debt and overpowered by men.","source":"Bukhari 6363"},{"id":"a_shakwa_ilallah","title":"La queja solo a Allah","title_ar":"الشكوى إلى الله وحده","title_en":"The complaint is only to Allah","arabic":"إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ","transliteration":"Innama ashku baththi wa huzni ila Allah","translation_es":"Yo solo me quejo de mi angustia y tristeza a Allah.","translation_ar":"إنما أشكو بثي وحزني إلى الله.","translation_en":"I only complain of my anguish and grief to Allah.","source":"Yusuf 86"},{"id":"a_enter_home","title":"Al entrar a casa","title_ar":"عند دخول المنزل","title_en":"Upon entering the home","arabic":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","transliteration":"Bismillahi walajna, wa bismillahi kharajna, wa 'ala Allahi Rabbina tawakkalna","translation_es":"En el nombre de Allah entramos, y en el nombre de Allah salimos, y en Allah nuestro Señor confiamos.","translation_ar":"بسم الله ولجنا، وبسم الله خرجنا، وعلى الله ربنا توكلنا.","translation_en":"In the name of Allah we enter, in the name of Allah we leave, and in Allah our Lord we trust.","source":"Abu Dawud 5096"},{"id":"a_exit_home","title":"Al salir de casa","title_ar":"عند الخروج من المنزل","title_en":"Upon leaving the home","arabic":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","transliteration":"Bismillah, tawakkaltu 'ala Allah, wa la hawla wa la quwwata illa billah","translation_es":"En el nombre de Allah, en Allah confío, y no hay poder ni fuerza sino en Allah.","translation_ar":"بسم الله، توكلت على الله، ولا حول ولا قوة إلا بالله.","translation_en":"In the name of Allah, I trust in Allah, and there is no power nor might except with Allah.","source":"Abu Dawud 5095"},{"id":"a_exit_home_dua","title":"Súplica al salir de casa","title_ar":"دعاء الخروج من المنزل","title_en":"Supplication upon leaving home","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ","transliteration":"Allahumma inni a'udhu bika an adilla aw udall, aw azilla aw uzall, aw azlima aw uzlam, aw ajhala aw yujhala 'alayya","translation_es":"¡Oh Allah! Me refugio en Ti de desviarme o de ser desviado, de resbalar o de ser hecho resbalar, de oprimir o de ser oprimido, de ser ignorante o de que se sea ignorante conmigo.","translation_ar":"اللهم إني أعوذ بك أن أضل أو أُضل، أو أزل أو أُزل، أو أظلم أو أُظلم، أو أجهل أو يُجهل علي.","translation_en":"O Allah! I seek refuge in You from going astray or being led astray, from slipping or being made to slip, from oppressing or being oppressed, from acting ignorantly or being treated ignorantly.","source":"Abu Dawud 5094"},{"id":"a_shaytan_no_share","title":"Al entrar y comer sin recordar Allah (protección)","title_ar":"عند الدخول والأكل بذكر الله (حماية)","title_en":"Entering and eating with remembrance of Allah (protection)","arabic":"بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ","transliteration":"Bismillahi fi awwalihi wa akhirihi","translation_es":"En el nombre de Allah al principio y al final.","translation_ar":"بسم الله في أوله وآخره.","translation_en":"In the name of Allah at its beginning and its end.","source":"Muslim 2018"},{"id":"a_call_prayer_home","title":"Al escuchar el adhan estando en casa","title_ar":"عند سماع الأذان في المنزل","title_en":"Upon hearing the adhan at home","arabic":"وَأَنَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا","transliteration":"Wa ana ashhadu an la ilaha illa Allah wahdahu la sharika lah, wa anna Muhammadan 'abduhu wa rasuluh, raditu billahi Rabban, wa bi-Muhammadin rasulan, wa bil-Islami dinan","translation_es":"Y yo atestiguo que no hay divinidad sino Allah, Único, sin asociados, y que Muhammad es Su siervo y Mensajero. Me complazco con Allah como Señor, con Muhammad como Mensajero, y con el Islam como religión.","translation_ar":"وأنا أشهد أن لا إله إلا الله وحده لا شريك له، وأن محمداً عبده ورسوله، رضيت بالله رباً، وبمحمد رسولاً، وبالإسلام ديناً.","translation_en":"And I bear witness that there is no god but Allah alone, without partner, and that Muhammad is His servant and Messenger. I am pleased with Allah as Lord, with Muhammad as Messenger, and with Islam as religion.","source":"Muslim 386"},{"id":"a_home_barakah","title":"Súplica por la bendición del hogar","title_ar":"دعاء بركة المنزل","title_en":"Supplication for the blessing of the home","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ، بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","transliteration":"Allahumma inni as'aluka khayra-l-mawliji wa khayra-l-makhraj, bismillahi walajna, wa bismillahi kharajna, wa 'ala Allahi Rabbina tawakkalna","translation_es":"¡Oh Allah! Te pido lo mejor de la entrada y lo mejor de la salida. En el nombre de Allah entramos, en el nombre de Allah salimos, y en Allah nuestro Señor confiamos.","translation_ar":"اللهم إني أسألك خير المولج وخير المخرج، بسم الله ولجنا، وبسم الله خرجنا، وعلى الله ربنا توكلنا.","translation_en":"O Allah! I ask You for the best of entrances and the best of exits. In the name of Allah we enter, in the name of Allah we leave, and in Allah our Lord we trust.","source":"Abu Dawud 5096"},{"id":"a_evening_amsayna","title":"Amsayna...","title_ar":"أمسينا...","title_en":"Amsayna (We have entered the evening)...","arabic":"أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","transliteration":"Amsayna wa amsa-l-mulku lillah...","translation_es":"Hemos anochecido y la soberanía pertenece a Allah, las alabanzas son para Allah...","translation_ar":"أمسينا وأمسى الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.","translation_en":"We have entered the evening and the whole kingdom belongs to Allah; all praise is for Allah. There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He has power over all things.","source":"Muslim"},{"id":"a_sayyid_evening","title":"Sayyid al-Istighfar","title_ar":"سيد الاستغفار","title_en":"Sayyid al-Istighfar (Master supplication for forgiveness)","arabic":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","transliteration":"Allahumma anta Rabbi, la ilaha illa anta...","translation_es":"Oh Allah, Tú eres mi Señor, no hay divinidad sino Tú...","translation_ar":"اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت...","translation_en":"O Allah, You are my Lord, there is no god but You. You created me and I am Your servant, and I abide by Your covenant and promise as best I can...","source":"Bukhari"},{"id":"a_evening_dua_protection","title":"Protección contra el mal","title_ar":"الحماية من الشر","title_en":"Protection against evil","arabic":"بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ","transliteration":"Bismillahi-lladhi la yadurru ma'asmihi shay'un...","translation_es":"En el nombre de Allah, con cuyo nombre nada puede dañar...","translation_ar":"بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم.","translation_en":"In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing.","source":"Abu Dawud"},{"id":"a_a_udhu_evening","title":"A'udhu bi-kalimat Allah","title_ar":"أعوذ بكلمات الله التامات","title_en":"A'udhu bi-kalimat Allah (I seek refuge in Allah's perfect words)","arabic":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","transliteration":"A'udhu bi-kalimat-illahi-t-tammati min sharri ma khalaq","translation_es":"Me refugio en las palabras perfectas de Allah del mal de lo que ha creado.","translation_ar":"أعوذ بكلمات الله التامات من شر ما خلق.","translation_en":"I seek refuge in the perfect words of Allah from the evil of what He has created.","source":"Muslim"},{"id":"a_evening_radhitu","title":"Radhitu billahi Rabba","title_ar":"رضيت بالله رباً","title_en":"Radhitu billahi Rabba (I am pleased with Allah as my Lord)","arabic":"رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا","transliteration":"Radhitu billahi Rabba, wa bil-Islami dina, wa bi-Muhammadin (saw) nabiyya","translation_es":"Estoy contento con Allah como mi Señor, con el Islam como mi religión, y con Muhammad ﷺ como mi Profeta.","translation_ar":"رضيت بالله رباً، وبالإسلام ديناً، وبمحمد ﷺ نبياً.","translation_en":"I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad ﷺ as my Prophet.","source":"Tirmidhi"},{"id":"a_before_eating","title":"Antes de comer (Bismillah)","title_ar":"قبل الأكل (البسملة)","title_en":"Before eating (Bismillah)","arabic":"بِسْمِ اللَّهِ","transliteration":"Bismillah","translation_es":"En el nombre de Allah.","translation_ar":"بسم الله.","translation_en":"In the name of Allah.","source":"Abu Dawud 3767"},{"id":"a_after_eating_1","title":"Después de comer (súplica corta)","title_ar":"بعد الأكل (دعاء قصير)","title_en":"After eating (short supplication)","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","transliteration":"Al-hamdu lillahi-lladhi at'amani hadha, wa razaqanihi min ghayri hawlin minni wa la quwwah","translation_es":"Alabado sea Allah, Quien me alimentó con esto y me lo proveyó sin ningún poder ni fuerza de mi parte.","translation_ar":"الحمد لله الذي أطعمني هذا، ورزقنيه من غير حول مني ولا قوة.","translation_en":"All praise is for Allah, Who fed me this and provided it to me without any power or might on my part.","source":"Abu Dawud 4023"},{"id":"a_after_eating_2","title":"Después de comer (súplica extendida)","title_ar":"بعد الأكل (دعاء موسّع)","title_en":"After eating (extended supplication)","arabic":"الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا","transliteration":"Al-hamdu lillahi hamdan kathiran tayyiban mubarakan fih, ghayra makfiyyin wa la muwadda'in wa la mustaghnan 'anhu Rabbana","translation_es":"Alabado sea Allah con muchas alabanzas buenas y bendecidas, sin cesar, sin despedida, y de las que no podemos prescindir, ¡oh Señor nuestro!","translation_ar":"الحمد لله حمداً كثيراً طيباً مباركاً فيه، غير مكفي ولا مودع ولا مستغنى عنه ربنا.","translation_en":"All praise is for Allah — abundant, good, blessed praise — unceasing, never parting, and indispensable, O our Lord!","source":"Bukhari 5458"},{"id":"a_guest_dua","title":"Súplica del invitado por el anfitrión","title_ar":"دعاء الضيف لصاحب الطعام","title_en":"The guest's supplication for the host","arabic":"اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ","transliteration":"Allahumma barik lahum fima razaqtahum, waghfir lahum warhamhum","translation_es":"¡Oh Allah! Bendícelos en lo que les has provisto, perdónalos y ten misericordia con ellos.","translation_ar":"اللهم بارك لهم فيما رزقتهم، واغفر لهم وارحمهم.","translation_en":"O Allah! Bless them in what You have provided them, forgive them and have mercy on them.","source":"Muslim 2042"},{"id":"a_iftar_dua","title":"Al romper el ayuno (Iftar)","title_ar":"عند الإفطار","title_en":"Upon breaking the fast (Iftar)","arabic":"ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","transliteration":"Dhahaba-z-zama', wabtallati-l-'uruq, wa thabata-l-ajru in sha' Allah","translation_es":"Se fue la sed, se humedecieron las venas, y la recompensa está asegurada si Allah quiere.","translation_ar":"ذهب الظمأ، وابتلت العروق، وثبت الأجر إن شاء الله.","translation_en":"The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills.","source":"Abu Dawud 2357"},{"id":"a_drink_milk","title":"Al beber leche","title_ar":"عند شرب اللبن","title_en":"Upon drinking milk","arabic":"اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ","transliteration":"Allahumma barik lana fihi wa zidna minhu","translation_es":"¡Oh Allah! Bendícenoslo y auméntanoslo.","translation_ar":"اللهم بارك لنا فيه وزدنا منه.","translation_en":"O Allah! Bless it for us and give us more of it.","source":"Abu Dawud 3730"},{"id":"a_water_dua","title":"Al beber agua (súplica general)","title_ar":"عند شرب الماء (دعاء عام)","title_en":"Upon drinking water (general supplication)","arabic":"الْحَمْدُ لِلَّهِ الَّذِي جَعَلَهُ عَذْبًا فُرَاتًا بِرَحْمَتِهِ، وَلَمْ يَجْعَلْهُ مِلْحًا أُجَاجًا بِذُنُوبِنَا","transliteration":"Al-hamdu lillahi-lladhi ja'alahu 'adhban furatan bi-rahmatih, wa lam yaj'alhu milhan ujajan bi-dhunubina","translation_es":"Alabado sea Allah, Quien lo hizo dulce y puro por Su misericordia, y no lo hizo salado y amargo por nuestros pecados.","translation_ar":"الحمد لله الذي جعله عذباً فراتاً برحمته، ولم يجعله ملحاً أجاجاً بذنوبنا.","translation_en":"All praise is for Allah, Who made it sweet and fresh by His mercy, and did not make it salty and bitter because of our sins.","source":"Ibn as-Sunni 466"},{"id":"a_end_meal_someone","title":"Súplica por quien te da de beber","title_ar":"الدعاء لمن سقاك","title_en":"Supplication for the one who gave you drink","arabic":"اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي","transliteration":"Allahumma at'im man at'amani, wasqi man saqani","translation_es":"¡Oh Allah! Alimenta a quien me alimentó y da de beber a quien me dio de beber.","translation_ar":"اللهم أطعم من أطعمني، واسق من سقاني.","translation_en":"O Allah! Feed the one who fed me and give drink to the one who gave me drink.","source":"Muslim 2055"},{"id":"a_invited_food","title":"Al ser invitado a comer","title_ar":"عند دعوتك إلى الطعام","title_en":"When invited to a meal","arabic":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ","transliteration":"Aftara 'indakumu-s-sa'imun, wa akala ta'amakumu-l-abrar, wa sallat 'alaykumu-l-mala'ikah","translation_es":"Que los que ayunan rompan su ayuno con vosotros, que los piadosos coman vuestra comida, y que los ángeles pidan bendiciones por vosotros.","translation_ar":"أفطر عندكم الصائمون، وأكل طعامكم الأبرار، وصلت عليكم الملائكة.","translation_en":"May the fasting break their fast with you, may the righteous eat your food, and may the angels invoke blessings upon you.","source":"Abu Dawud 3854"},{"id":"a_suhoor_barakah","title":"Sobre el Suhoor (comida antes del ayuno)","title_ar":"في السحور","title_en":"About Suhoor (pre-dawn meal)","arabic":"تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً","transliteration":"Tasahharu fa-inna fi-s-suhuri barakah","translation_es":"Tomad el suhoor, pues en el suhoor hay bendición.","translation_ar":"تسحروا فإن في السحور بركة.","translation_en":"Take the suhoor, for in the suhoor there is blessing.","source":"Bukhari 1923"},{"id":"a_new_fruit","title":"Al ver o probar una fruta nueva de temporada","title_ar":"عند رؤية أول الثمار","title_en":"Upon seeing the first fruit of the season","arabic":"اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا","transliteration":"Allahumma barik lana fi thamarina, wa barik lana fi madinatina, wa barik lana fi sa'ina, wa barik lana fi muddina","translation_es":"¡Oh Allah! Bendícenos en nuestros frutos, en nuestra ciudad, en nuestra medida (grande) y en nuestra medida (pequeña).","translation_ar":"اللهم بارك لنا في ثمرنا، وبارك لنا في مدينتنا، وبارك لنا في صاعنا، وبارك لنا في مدنا.","translation_en":"O Allah! Bless us in our fruits, in our city, in our sa' (large measure) and in our mudd (small measure).","source":"Muslim 1373"},{"id":"a_kahf_recitation","title":"Recitar la Sura Al-Kahf","title_ar":"قراءة سورة الكهف","title_en":"Reciting Surah Al-Kahf","arabic":"مَنْ قَرَأَ سُورَةَ الْكَهْفِ فِي يَوْمِ الْجُمُعَةِ أَضَاءَ لَهُ مِنَ النُّورِ مَا بَيْنَ الْجُمُعَتَيْنِ","transliteration":"Man qara'a Suratal-Kahfi fi yawmi-l-Jumu'ati ada'a lahu mina-n-nuri ma bayna-l-Jumu'atayn","translation_es":"Quien recite la Sura Al-Kahf el día del viernes, se le iluminará una luz entre los dos viernes.","translation_ar":"من قرأ سورة الكهف في يوم الجمعة أضاء له من النور ما بين الجمعتين.","translation_en":"Whoever recites Surah Al-Kahf on Friday will have a light shining for him between the two Fridays.","source":"Hakim 3392"},{"id":"a_salah_ala_nabi","title":"Multiplicar las bendiciones al Profeta ﷺ","title_ar":"الإكثار من الصلاة على النبي ﷺ","title_en":"Abundant blessings upon the Prophet ﷺ","arabic":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ","transliteration":"Allahumma salli 'ala Muhammadin wa 'ala ali Muhammad, kama sallayta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidun Majid","translation_es":"¡Oh Allah! Concede bendiciones a Muhammad y a la familia de Muhammad, como se las concediste a Ibrahim y a la familia de Ibrahim. Ciertamente, Tú eres Digno de Alabanza, Glorioso.","translation_ar":"اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم وعلى آل إبراهيم، إنك حميد مجيد.","translation_en":"O Allah! Send blessings upon Muhammad and the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim. Indeed, You are Praiseworthy, Glorious.","source":"Abu Dawud 1047"},{"id":"a_sa'at_ijabah","title":"La hora de aceptación del viernes","title_ar":"ساعة الإجابة يوم الجمعة","title_en":"The hour of acceptance on Friday","arabic":"فِي الْجُمُعَةِ سَاعَةٌ لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ وَهُوَ يُصَلِّي يَسْأَلُ اللَّهَ شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ","transliteration":"Fi-l-Jumu'ati sa'atun la yuwafiquha 'abdun muslimun wa huwa yusalli yas'alu-llaha shay'an illa a'tahu iyyah","translation_es":"Hay una hora del viernes en la que ningún siervo musulmán que esté rezando y pida algo a Allah, deja de recibirlo.","translation_ar":"في الجمعة ساعة لا يوافقها عبد مسلم وهو يصلي يسأل الله شيئاً إلا أعطاه إياه.","translation_en":"There is an hour on Friday during which no Muslim servant, standing in prayer and asking Allah for something, fails to receive it.","source":"Bukhari 935"},{"id":"a_ghusl_friday","title":"Ghusl del viernes (baño ritual)","title_ar":"غسل يوم الجمعة","title_en":"Friday ghusl (ritual bath)","arabic":"غُسْلُ يَوْمِ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ","transliteration":"Ghuslu yawmi-l-jumu'ati wajibun 'ala kulli muhtalim","translation_es":"El ghusl del viernes es (muy) recomendado sobre todo adulto.","translation_ar":"غسل يوم الجمعة واجب (مؤكد) على كل محتلم.","translation_en":"The Friday ghusl is (strongly) prescribed upon every adult.","source":"Bukhari 879"},{"id":"a_early_jumu'ah","title":"Llegar temprano a la Jumu'ah","title_ar":"التبكير إلى الجمعة","title_en":"Arriving early to the Jumu'ah","arabic":"مَنِ اغْتَسَلَ يَوْمَ الْجُمُعَةِ ثُمَّ أَتَى الْجُمُعَةَ فَصَلَّى مَا قُدِّرَ لَهُ ثُمَّ أَنْصَتَ حَتَّى يَفْرُغَ مِنْ خُطْبَتِهِ ثُمَّ يُصَلِّي مَعَهُ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى","transliteration":"Manightasala yawma-l-Jumu'ati thumma ata-l-Jumu'ata fasalla ma quddira lahu thumma ansata hatta yafrugha min khutbatih...","translation_es":"Quien haga ghusl el viernes, luego venga a la Jumu'ah, rece lo que le sea prescrito, escuche en silencio hasta que termine el khutbah, y luego rece con él, se le perdonará lo que hay entre este viernes y el siguiente.","translation_ar":"من اغتسل يوم الجمعة ثم أتى الجمعة فصلى ما قُدر له ثم أنصت حتى يفرغ من خطبته ثم يصلي معه غُفر له ما بينه وبين الجمعة الأخرى.","translation_en":"Whoever performs ghusl on Friday, then comes to the Jumu'ah, prays what is prescribed for him, listens silently until the khutbah ends, then prays with the imam — will be forgiven what is between this Friday and the next.","source":"Muslim 857"},{"id":"a_silent_khutbah","title":"Guardar silencio durante el khutbah","title_ar":"الإنصات أثناء الخطبة","title_en":"Keeping silent during the khutbah","arabic":"إِذَا قُلْتَ لِصَاحِبِكَ أَنْصِتْ، يَوْمَ الْجُمُعَةِ وَالْإِمَامُ يَخْطُبُ، فَقَدْ لَغَوْتَ","transliteration":"Idha qulta li-sahibika ansit, yawma-l-Jumu'ati wa-l-imamu yakhtub, faqad laghawt","translation_es":"Si dices a tu compañero: \"Silencio\", el viernes mientras el imam predica, entonces has hablado en vano.","translation_ar":"إذا قلت لصاحبك أنصت، يوم الجمعة والإمام يخطب، فقد لغوت.","translation_en":"If you tell your companion \"be quiet\" on Friday while the imam is delivering the khutbah, you have spoken idly.","source":"Bukhari 934"},{"id":"a_best_day","title":"El mejor día en el que sale el sol","title_ar":"خير يوم طلعت عليه الشمس","title_en":"The best day on which the sun rises","arabic":"خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَفِيهِ أُدْخِلَ الْجَنَّةَ، وَفِيهِ أُخْرِجَ مِنْهَا، وَلَا تَقُومُ السَّاعَةُ إِلَّا فِي يَوْمِ الْجُمُعَةِ","transliteration":"Khayru yawmin tala'at 'alayhi-sh-shamsu yawmu-l-Jumu'ah, fihi khuliqa Adam, wa fihi udkhila-l-jannah, wa fihi ukhrija minha, wa la taqumu-s-sa'atu illa fi yawmi-l-Jumu'ah","translation_es":"El mejor día en el que sale el sol es el viernes. En él fue creado Adán, en él entró al Paraíso, en él fue sacado de él, y la Hora no se establecerá sino en el día del viernes.","translation_ar":"خير يوم طلعت عليه الشمس يوم الجمعة، فيه خُلق آدم، وفيه أُدخل الجنة، وفيه أُخرج منها، ولا تقوم الساعة إلا في يوم الجمعة.","translation_en":"The best day on which the sun rises is Friday. On it Adam was created, on it he entered Paradise, on it he was taken out of it, and the Hour will not be established except on a Friday.","source":"Muslim 854"},{"id":"a_friday_night_dua","title":"La noche del jueves al viernes","title_ar":"ليلة الجمعة","title_en":"The night of Friday (Thursday night)","arabic":"اللَّيْلَةُ الْغَرَّاءُ وَالْيَوْمُ الْأَزْهَرُ","transliteration":"Al-laylatu-l-gharra'u wa-l-yawmu-l-azhar","translation_es":"La noche brillante y el día resplandeciente.","translation_ar":"الليلة الغراء واليوم الأزهر.","translation_en":"The radiant night and the shining day.","source":"Bayhaqi Shu'ab al-Iman"},{"id":"a_walking_jumu'ah","title":"Caminar a la Jumu'ah","title_ar":"الذهاب مشياً إلى الجمعة","title_en":"Walking to the Jumu'ah","arabic":"مَنْ غَسَّلَ يَوْمَ الْجُمُعَةِ وَاغْتَسَلَ، ثُمَّ بَكَّرَ وَابْتَكَرَ، وَمَشَى وَلَمْ يَرْكَبْ، وَدَنَا مِنَ الْإِمَامِ فَاسْتَمَعَ وَلَمْ يَلْغُ، كَانَ لَهُ بِكُلِّ خُطْوَةٍ عَمَلُ سَنَةٍ","transliteration":"Man ghassala yawma-l-Jumu'ati waghtasal, thumma bakkara wabtakar, wa masha wa lam yarkab, wa dana mina-l-imami fastama'a wa lam yalghu, kana lahu bi-kulli khutwatin 'amalu sanah","translation_es":"Quien se lave y haga ghusl el viernes, luego madrugue y llegue temprano, camine sin montar, se acerque al imam, escuche y no hable en vano — tendrá por cada paso la recompensa de un año de actos.","translation_ar":"من غسّل يوم الجمعة واغتسل، ثم بكّر وابتكر، ومشى ولم يركب، ودنا من الإمام فاستمع ولم يلغُ، كان له بكل خطوة عمل سنة.","translation_en":"Whoever washes and performs ghusl on Friday, then sets out early and arrives early, walks without riding, draws near the imam, listens and does not speak idly — will have for every step the reward of a year of deeds.","source":"Abu Dawud 345"},{"id":"a_du'a_after_jumu'ah","title":"Súplica al terminar la Jumu'ah","title_ar":"دعاء بعد الجمعة","title_en":"Supplication after the Jumu'ah","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ الْحَلَالِ الطَّيِّبِ، وَأَعُوذُ بِكَ مِنْ فَضْلِ كُلِّ ظَالِمٍ","transliteration":"Allahumma inni as'aluka min fadlika-l-halali-t-tayyib, wa a'udhu bika min fadli kulli zalim","translation_es":"¡Oh Allah! Te pido de Tu favor lícito y bueno, y me refugio en Ti del favor de todo opresor.","translation_ar":"اللهم إني أسألك من فضلك الحلال الطيب، وأعوذ بك من فضل كل ظالم.","translation_en":"O Allah! I ask You for Your lawful, good bounty, and I seek refuge in You from the bounty of every oppressor.","source":"Ibn Majah 3312"},{"id":"a_morning_amsayna","title":"Asbahna...","title_ar":"أصبحنا...","title_en":"Asbahna (We have entered the morning)...","arabic":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","transliteration":"Asbahna wa asbaha-l-mulku lillah, wal-hamdu lillah...","translation_es":"Hemos amanecido y la soberanía pertenece a Allah, las alabanzas son para Allah. No hay divinidad sino Allah, Único, sin asociado. Suyos son el reino y la alabanza, y Él es Omnipotente sobre todas las cosas.","translation_ar":"أصبحنا وأصبح الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير.","translation_en":"We have entered the morning and the whole kingdom belongs to Allah; all praise is for Allah. There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He has power over all things.","source":"Muslim"},{"id":"a_subhanallah_morning","title":"Subhanallah wa bi hamdihi","title_ar":"سبحان الله وبحمده","title_en":"Subhanallah wa bi hamdihi","arabic":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","transliteration":"Subhanallahi wa bihamdihi","translation_es":"Glorificado sea Allah y con Su alabanza.","translation_ar":"سبحان الله وبحمده.","translation_en":"Glory be to Allah and praise be to Him.","source":"Bukhari y Muslim"},{"id":"a_astaghfirullah_morning","title":"Astaghfirullah","title_ar":"أستغفر الله","title_en":"Astaghfirullah (I seek Allah's forgiveness)","arabic":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","transliteration":"Astaghfirullaha wa atubu ilayhi","translation_es":"Pido perdón a Allah y me arrepiento ante Él.","translation_ar":"أستغفر الله وأتوب إليه.","translation_en":"I seek Allah's forgiveness and turn to Him in repentance.","source":"Muslim"},{"id":"a_enter_mosque","title":"Al entrar a la mezquita","title_ar":"عند دخول المسجد","title_en":"Upon entering the mosque","arabic":"أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ. بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","transliteration":"A'udhu billahi-l-'Azim, wa bi-wajhihi-l-Karim, wa sultanihi-l-qadim, mina-sh-shaytani-r-rajim. Bismillah, was-salatu was-salamu 'ala Rasulillah, Allahumma-ftah li abwaba rahmatik","translation_es":"Me refugio en Allah, el Grandioso, en Su Noble Rostro y en Su Poder eterno, del demonio expulsado. En el nombre de Allah, y las bendiciones y la paz sean con el Mensajero de Allah. ¡Oh Allah! Ábreme las puertas de Tu misericordia.","translation_ar":"أعوذ بالله العظيم، وبوجهه الكريم، وسلطانه القديم، من الشيطان الرجيم. بسم الله، والصلاة والسلام على رسول الله، اللهم افتح لي أبواب رحمتك.","translation_en":"I seek refuge in Allah the Magnificent, in His Noble Face and His eternal Dominion, from the accursed devil. In the name of Allah, and blessings and peace upon the Messenger of Allah. O Allah! Open for me the doors of Your mercy.","source":"Abu Dawud 466"},{"id":"a_exit_mosque","title":"Al salir de la mezquita","title_ar":"عند الخروج من المسجد","title_en":"Upon leaving the mosque","arabic":"بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ","transliteration":"Bismillah, was-salatu was-salamu 'ala Rasulillah, Allahumma inni as'aluka min fadlik, Allahumma-'simni mina-sh-shaytani-r-rajim","translation_es":"En el nombre de Allah, y las bendiciones y la paz sean con el Mensajero de Allah. ¡Oh Allah! Te pido de Tu favor. ¡Oh Allah! Protégeme del demonio expulsado.","translation_ar":"بسم الله، والصلاة والسلام على رسول الله، اللهم إني أسألك من فضلك، اللهم اعصمني من الشيطان الرجيم.","translation_en":"In the name of Allah, and blessings and peace upon the Messenger of Allah. O Allah! I ask You of Your bounty. O Allah! Protect me from the accursed devil.","source":"Muslim 713"},{"id":"a_tahiyyat_masjid","title":"Tahiyyat al-Masjid (saludo a la mezquita)","title_ar":"تحية المسجد","title_en":"Tahiyyat al-Masjid (greeting of the mosque)","arabic":"رَكْعَتَانِ خَفِيفَتَانِ قَبْلَ الْجُلُوسِ","transliteration":"Rak'atani khafifatani qabla-l-julus","translation_es":"Dos rak'as ligeras antes de sentarse.","translation_ar":"ركعتان خفيفتان قبل الجلوس.","translation_en":"Two light rak'ahs before sitting down.","source":"Bukhari 444"},{"id":"a_adhan_response","title":"Al escuchar el adhan (en la mezquita o fuera)","title_ar":"عند سماع الأذان","title_en":"Upon hearing the adhan","arabic":"اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ","transliteration":"Allahumma Rabba hadhihi-d-da'wati-t-tammah, was-salati-l-qa'imah, ati Muhammadan-l-wasilata wal-fadilah, wab'athhu maqaman mahmudan-lladhi wa'adtah","translation_es":"¡Oh Allah, Señor de este llamado perfecto y de la oración establecida! Concede a Muhammad la intercesión y la excelencia, y elévalo al puesto elogiado que le has prometido.","translation_ar":"اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته.","translation_en":"O Allah, Lord of this perfect call and the established prayer! Grant Muhammad the wasilah and the excellence, and raise him to the praised station You have promised him.","source":"Bukhari 614"},{"id":"a_between_adhan_iqamah","title":"Entre el adhan y el iqamah","title_ar":"بين الأذان والإقامة","title_en":"Between the adhan and the iqamah","arabic":"الدُّعَاءُ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ لَا يُرَدُّ","transliteration":"Ad-du'a'u bayna-l-adhani wa-l-iqamati la yuradd","translation_es":"La súplica entre el adhan y el iqamah no es rechazada.","translation_ar":"الدعاء بين الأذان والإقامة لا يُرد.","translation_en":"The supplication between the adhan and the iqamah is not rejected.","source":"Abu Dawud 521"},{"id":"a_i'tikaf_intention","title":"Intención de I'tikaf o permanencia en la mezquita","title_ar":"نية الاعتكاف أو المكث في المسجد","title_en":"Intention of I'tikaf or staying in the mosque","arabic":"نَوَيْتُ الِاعْتِكَافَ فِي هَذَا الْمَسْجِدِ لِلَّهِ تَعَالَى","transliteration":"Nawaytu-l-i'tikafa fi hadha-l-masjidi lillahi ta'ala","translation_es":"He hecho la intención de retirarme en esta mezquita por Allah, Exaltado sea.","translation_ar":"نويت الاعتكاف في هذا المسجد لله تعالى.","translation_en":"I have intended to seclude myself in this mosque for Allah, the Exalted.","source":"Bukhari 2026"},{"id":"a_baqarah_last_two","title":"Los dos últimos versos de Al-Baqarah","title_ar":"خواتيم سورة البقرة","title_en":"The last two verses of Al-Baqarah","arabic":"آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ... رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا","transliteration":"Amana-r-rasulu bima unzila ilayhi min Rabbihi wa-l-mu'minun... Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna","translation_es":"El Mensajero creyó en lo que se le hizo descender de su Señor, y los creyentes también. Todos han creído en Allah, en Sus ángeles, en Sus Libros y en Sus Mensajeros... \"¡Señor nuestro! No nos hagas cargar con lo que no podamos. Perdónanos, borra nuestras faltas, y ten misericordia con nosotros\".","translation_ar":"آمن الرسول بما أُنزل إليه من ربه والمؤمنون، كلٌّ آمن بالله وملائكته وكتبه ورسله لا نفرق بين أحد من رسله... ربنا ولا تحملنا ما لا طاقة لنا به، واعف عنا واغفر لنا وارحمنا.","translation_en":"The Messenger believed in what was revealed to him from his Lord, and so did the believers. All of them believed in Allah, His angels, His Books and His Messengers... \"Our Lord! Do not burden us with what we cannot bear. Pardon us, forgive us, and have mercy on us\".","source":"Al-Baqarah 285-286"},{"id":"a_sura_ikhlas","title":"Sura Al-Ikhlas (Sinceridad)","title_ar":"سورة الإخلاص","title_en":"Surah Al-Ikhlas (Sincerity)","arabic":"قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","transliteration":"Qul huwa-llahu ahad. Allahu-s-samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad","translation_es":"Di: \"Él es Allah, Uno. Allah es el Absoluto. No engendró ni fue engendrado. Y no hay nadie que se le compare\".","translation_ar":"قل هو الله أحد، الله الصمد، لم يلد ولم يولد، ولم يكن له كفواً أحد.","translation_en":"Say: \"He is Allah, the One. Allah, the Absolute. He begets not, nor was He begotten. And there is none comparable to Him\".","source":"Al-Ikhlas 1-4"},{"id":"a_sura_falaq","title":"Sura Al-Falaq (El Amanecer)","title_ar":"سورة الفلق","title_en":"Surah Al-Falaq (The Daybreak)","arabic":"قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ","transliteration":"Qul a'udhu bi-Rabbi-l-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharri-n-naffathati fi-l-'uqad. Wa min sharri hasidin idha hasad","translation_es":"Di: \"Me refugio en el Señor del amanecer del mal de lo que ha creado, del mal de la noche cuando se instala, del mal de las que soplan en los nudos (brujería), y del mal del envidioso cuando envidia\".","translation_ar":"قل أعوذ برب الفلق، من شر ما خلق، ومن شر غاسق إذا وقب، ومن شر النفاثات في العقد، ومن شر حاسد إذا حسد.","translation_en":"Say: \"I seek refuge in the Lord of the daybreak, from the evil of what He created, from the evil of darkness when it settles, from the evil of those who blow on knots (sorcery), and from the evil of an envier when he envies\".","source":"Al-Falaq 1-5"},{"id":"a_sura_nas","title":"Sura An-Nas (Los Hombres)","title_ar":"سورة الناس","title_en":"Surah An-Nas (Mankind)","arabic":"قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ","transliteration":"Qul a'udhu bi-Rabbi-n-nas. Maliki-n-nas. Ilahi-n-nas. Min sharri-l-waswasi-l-khannas. Alladhi yuwaswisu fi suduri-n-nas. Mina-l-jinnati wa-n-nas","translation_es":"Di: \"Me refugio en el Señor de los hombres, Soberano de los hombres, Dios de los hombres, del mal del susurrador furtivo que susurra en los pechos de los hombres, ya sea de los yinn o de los hombres\".","translation_ar":"قل أعوذ برب الناس، ملك الناس، إله الناس، من شر الوسواس الخناس، الذي يوسوس في صدور الناس، من الجنة والناس.","translation_en":"Say: \"I seek refuge in the Lord of mankind, the Sovereign of mankind, the God of mankind, from the evil of the retreating whisperer who whispers in the breasts of mankind, from among jinn and men\".","source":"An-Nas 1-6"},{"id":"a_sura_fatiha","title":"Sura Al-Fatiha (La Apertura)","title_ar":"سورة الفاتحة","title_en":"Surah Al-Fatiha (The Opening)","arabic":"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَٰنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ","transliteration":"Bismillahi-r-Rahmani-r-Rahim. Al-hamdu lillahi Rabbi-l-'alamin. Ar-Rahmani-r-Rahim. Maliki yawmi-d-din. Iyyaka na'budu wa iyyaka nasta'in. Ihdina-s-sirata-l-mustaqim. Sirata-lladhina an'amta 'alayhim ghayri-l-maghdubi 'alayhim wa la-d-dallin","translation_es":"En el nombre de Allah, el Compasivo, el Misericordioso. Alabado sea Allah, Señor de los mundos, el Compasivo, el Misericordioso, Soberano del Día del Juicio. A Ti adoramos y a Ti pedimos ayuda. Guíanos por el camino recto, el camino de aquellos que has agraciado, no el de los que han incurrido en ira ni el de los extraviados.","translation_ar":"بسم الله الرحمن الرحيم، الحمد لله رب العالمين، الرحمن الرحيم، مالك يوم الدين، إياك نعبد وإياك نستعين، اهدنا الصراط المستقيم، صراط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالين.","translation_en":"In the name of Allah, the Most Gracious, the Most Merciful. All praise is for Allah, Lord of the worlds, the Most Gracious, the Most Merciful, Master of the Day of Judgment. You alone we worship, and You alone we ask for help. Guide us to the straight path, the path of those You have blessed, not of those who earned Your anger nor of those who went astray.","source":"Al-Fatiha 1-7"},{"id":"a_dua_ibrahim","title":"Súplica de Ibrahim عليه السلام","title_ar":"دعاء إبراهيم عليه السلام","title_en":"Supplication of Ibrahim عليه السلام","arabic":"رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ","transliteration":"Rabbana taqabbal minna, innaka anta-s-Sami'u-l-'Alim","translation_es":"¡Señor nuestro! Acéptanos (nuestras obras). Ciertamente, Tú eres Quien todo lo oye, Todo lo sabe.","translation_ar":"ربنا تقبل منا، إنك أنت السميع العليم.","translation_en":"Our Lord! Accept this from us. Indeed, You are the All-Hearing, the All-Knowing.","source":"Al-Baqarah 127"},{"id":"a_rabbana_dunya_akhirah","title":"Rabbana atina fi-d-dunya hasanah","title_ar":"ربنا آتنا في الدنيا حسنة","title_en":"Rabbana atina fi-d-dunya hasanah (Our Lord, give us good in this world)","arabic":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","transliteration":"Rabbana atina fi-d-dunya hasanatan wa fi-l-akhirati hasanatan wa qina 'adhaba-n-nar","translation_es":"¡Señor nuestro! Danos lo bueno en esta vida y lo bueno en la otra, y protégenos del castigo del Fuego.","translation_ar":"ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار.","translation_en":"Our Lord! Give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.","source":"Al-Baqarah 201"},{"id":"a_dua_musa","title":"Súplica de Musa عليه السلام","title_ar":"دعاء موسى عليه السلام","title_en":"Supplication of Musa عليه السلام","arabic":"رَبِّ اشْرَحْ لِي صَدْرِي ۝ وَيَسِّرْ لِي أَمْرِي ۝ وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي ۝ يَفْقَهُوا قَوْلِي","transliteration":"Rabbi-shrah li sadri, wa yassir li amri, wahlul 'uqdatan min lisani, yafqahu qawli","translation_es":"¡Señor mío! Ensancha mi pecho, facilítame mi asunto, desata el nudo de mi lengua, para que comprendan mis palabras.","translation_ar":"رب اشرح لي صدري، ويسر لي أمري، واحلل عقدة من لساني، يفقهوا قولي.","translation_en":"My Lord! Expand for me my chest, ease my task for me, and untie the knot from my tongue, that they may understand my speech.","source":"Ta-Ha 25-28"},{"id":"a_dua_nuh","title":"Súplica de Nuh عليه السلام al desembarcar","title_ar":"دعاء نوح عليه السلام عند النزول","title_en":"Supplication of Nuh عليه السلام upon disembarking","arabic":"رَبِّ أَنْزِلْنِي مُنْزَلًا مُبَارَكًا وَأَنْتَ خَيْرُ الْمُنْزِلِينَ","transliteration":"Rabbi anzilni munzalan mubarakan wa anta khayru-l-munzilin","translation_es":"¡Señor mío! Hazme descender en un lugar bendecido, pues Tú eres el Mejor en dar refugio.","translation_ar":"رب أنزلني منزلاً مباركاً وأنت خير المنزلين.","translation_en":"My Lord! Cause me to land at a blessed landing place, for You are the best of those who give lodging.","source":"Al-Mu'minun 29"},{"id":"a_sleep_ayat_kursi","title":"Ayat al-Kursi","title_ar":"آية الكرسي","title_en":"Ayat al-Kursi","arabic":"اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ","transliteration":"Allahu la ilaha illa Huwa, Al-Hayyul-Qayyum...","translation_es":"Allah, no hay más divinidad que Él, el Viviente, el Eterno...","translation_ar":"الله لا إله إلا هو الحي القيوم، لا تأخذه سنة ولا نوم...","translation_en":"Allah — there is no god but He, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him...","source":"Bukhari"},{"id":"a_sleep_subhanallah","title":"Tasbih antes de dormir","title_ar":"تسبيح قبل النوم","title_en":"Tasbih before sleep","arabic":"سُبْحَانَ اللَّهِ • الْحَمْدُ لِلَّهِ • اللَّهُ أَكْبَرُ","transliteration":"Subhanallah (33) • Alhamdulillah (33) • Allahu Akbar (34)","translation_es":"Glorificado sea Allah / Alabado sea Allah / Allah es el más Grande","translation_ar":"سبحان الله (33) • الحمد لله (33) • الله أكبر (34)","translation_en":"Glory be to Allah / All praise is for Allah / Allah is the Greatest","source":"Bukhari"},{"id":"a_sleep_bismika","title":"Bismika Allahumma...","title_ar":"باسمك اللهم...","title_en":"Bismika Allahumma (In Your name, O Allah)...","arabic":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","transliteration":"Bismika Allahumma amutu wa ahya","translation_es":"Con Tu nombre, oh Allah, muero y vivo.","translation_ar":"باسمك اللهم أموت وأحيا.","translation_en":"In Your name, O Allah, I die and I live.","source":"Bukhari"},{"id":"a_sleep_amantu","title":"Amantu bi kitabik","title_ar":"آمنت بكتابك","title_en":"Amantu bi kitabik (I believe in Your Book)","arabic":"اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ","transliteration":"Allahumma aslamtu nafsi ilayk, wa fawwadtu amri ilayk...","translation_es":"Oh Allah, me he sometido a Ti, he confiado mi asunto a Ti, he vuelto mi rostro hacia Ti, he buscado refugio en Ti, con esperanza y temor. No hay refugio ni salvación de Ti excepto en Ti. He creído en Tu libro que revelaste y en Tu Profeta que enviaste.","translation_ar":"اللهم أسلمت نفسي إليك، وفوضت أمري إليك، ووجهت وجهي إليك، وألجأت ظهري إليك، رغبة ورهبة إليك، لا ملجأ ولا منجا منك إلا إليك، آمنت بكتابك الذي أنزلت، وبنبيك الذي أرسلت.","translation_en":"O Allah, I have submitted myself to You, entrusted my affairs to You, turned my face to You, and sought Your protection, in hope and fear of You. There is no refuge or escape from You except to You. I believe in Your Book which You revealed and in Your Prophet whom You sent.","source":"Bukhari"},{"id":"a_travel_start","title":"Al comenzar el viaje (al montar en el vehículo)","title_ar":"عند بدء السفر (الركوب)","title_en":"Upon starting the journey (boarding the vehicle)","arabic":"بِسْمِ اللَّهِ، الْحَمْدُ لِلَّهِ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ","transliteration":"Bismillah, al-hamdu lillah, subhana-lladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila Rabbina la-munqalibun","translation_es":"En el nombre de Allah. Alabado sea Allah. Glorificado sea Aquel que puso esto a nuestro servicio, pues nosotros no habríamos podido dominarlo; en verdad, a nuestro Señor hemos de retornar.","translation_ar":"بسم الله، الحمد لله، سبحان الذي سخر لنا هذا وما كنا له مقرنين، وإنا إلى ربنا لمنقلبون.","translation_en":"In the name of Allah. All praise is for Allah. Glory be to the One who subjected this to us, for we could never have subdued it ourselves; and indeed, to our Lord we shall return.","source":"Muslim 1342"},{"id":"a_travel_dua_full","title":"Súplica completa del viaje","title_ar":"دعاء السفر الكامل","title_en":"The complete travel supplication","arabic":"اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ","transliteration":"Allahumma inna nas'aluka fi safarina hadha-l-birra wat-taqwa, wa mina-l-'amali ma tarda, Allahumma hawwin 'alayna safarana hadha watwi 'anna bu'dah, Allahumma anta-s-sahibu fi-s-safar, wal-khalifatu fi-l-ahl","translation_es":"¡Oh Allah! Te pedimos en este viaje piedad, temor de Ti, y las obras con las que Te complazcas. ¡Oh Allah! Facilítanos este viaje y acorta su distancia. ¡Oh Allah! Tú eres el Compañero en el viaje y el Guardián de la familia.","translation_ar":"اللهم إنا نسألك في سفرنا هذا البر والتقوى، ومن العمل ما ترضى، اللهم هون علينا سفرنا هذا واطو عنا بعده، اللهم أنت الصاحب في السفر، والخليفة في الأهل.","translation_en":"O Allah! We ask You in this journey for righteousness and piety, and for deeds that please You. O Allah! Make this journey easy for us and shorten its distance. O Allah! You are the Companion on the journey and the Guardian over the family.","source":"Muslim 1342"},{"id":"a_entering_town","title":"Al entrar en un pueblo o ciudad","title_ar":"عند دخول قرية أو مدينة","title_en":"Upon entering a town or city","arabic":"اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الْأَرَضِينَ السَّبْعِ وَمَا أَقْلَلْنَ، أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ وَخَيْرَ أَهْلِهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا","transliteration":"Allahumma Rabba-s-samawati-s-sab'i wa ma azlaln, wa Rabba-l-aradina-s-sab'i wa ma aqlaln, as'aluka khayra hadhihi-l-qaryati wa khayra ahliha, wa a'udhu bika min sharriha wa sharri ahliha","translation_es":"¡Oh Allah! Señor de los siete cielos y lo que sombrean, Señor de las siete tierras y lo que llevan, Te pido el bien de esta ciudad y el bien de sus habitantes, y me refugio en Ti de su mal y del mal de sus habitantes.","translation_ar":"اللهم رب السماوات السبع وما أظللن، ورب الأرضين السبع وما أقللن، أسألك خير هذه القرية وخير أهلها، وأعوذ بك من شرها وشر أهلها.","translation_en":"O Allah! Lord of the seven heavens and what they shade, Lord of the seven earths and what they carry, I ask You for the good of this town and the good of its people, and I seek refuge in You from its evil and the evil of its people.","source":"Hakim al-Mustadrak 1/615"},{"id":"a_return_travel","title":"Al regresar del viaje","title_ar":"عند العودة من السفر","title_en":"Upon returning from the journey","arabic":"آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ","transliteration":"Ayibun, ta'ibun, 'abidun, li-Rabbina hamidun","translation_es":"Volvemos, nos arrepentimos, adoramos y alabamos a nuestro Señor.","translation_ar":"آيبون، تائبون، عابدون، لربنا حامدون.","translation_en":"We return, repenting, worshipping, and praising our Lord.","source":"Muslim 1342"},{"id":"a_travel_dua_return_extended","title":"Súplica ampliada al volver del viaje","title_ar":"دعاء موسّع عند العودة من السفر","title_en":"Extended supplication upon returning from travel","arabic":"آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ","transliteration":"Ayibun, ta'ibun, 'abidun, li-Rabbina hamidun, sadaqa-llahu wa'dah, wa nasara 'abdah, wa hazama-l-ahzaba wahdah","translation_es":"Volvemos, nos arrepentimos, adoramos y alabamos a nuestro Señor. Allah cumplió Su promesa, dio la victoria a Su siervo y derrotó Él solo a los ejércitos aliados.","translation_ar":"آيبون، تائبون، عابدون، لربنا حامدون، صدق الله وعده، ونصر عبده، وهزم الأحزاب وحده.","translation_en":"We return, repenting, worshipping, and praising our Lord. Allah fulfilled His promise, granted victory to His servant, and defeated the confederates alone.","source":"Muslim 1344"},{"id":"a_boarding_ship_plane","title":"Al embarcar en un barco (o avión)","title_ar":"عند ركوب السفينة (أو الطائرة)","title_en":"Upon boarding a ship (or plane)","arabic":"بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسَاهَا، إِنَّ رَبِّي لَغَفُورٌ رَحِيمٌ","transliteration":"Bismillahi majreha wa mursaha, inna Rabbi la-Ghafurun Rahim","translation_es":"En el nombre de Allah es su navegación y su fondeo. Ciertamente, mi Señor es Perdonador, Misericordioso.","translation_ar":"بسم الله مجراها ومرساها، إن ربي لغفور رحيم.","translation_en":"In the name of Allah is its sailing and its anchoring. Indeed, my Lord is Forgiving, Merciful.","source":"Hud 41"},{"id":"a_farewell_traveler","title":"Despedir al viajero","title_ar":"توديع المسافر","title_en":"Bidding farewell to the traveler","arabic":"أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ","transliteration":"Astawdi'u-llaha dinaka wa amanataka wa khawatima 'amalik","translation_es":"Confío a Allah tu religión, tu confianza (bienes/familia) y el fin de tus obras.","translation_ar":"أستودع الله دينك وأمانتك وخواتيم عملك.","translation_en":"I entrust to Allah your religion, your trust (belongings/family), and the conclusion of your deeds.","source":"Tirmidhi 3443"},{"id":"a_wake_hamd","title":"Alhamdulillah al despertar","title_ar":"الحمد لله عند الاستيقاظ","title_en":"Alhamdulillah upon waking","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","transliteration":"Al-hamdu lillahi-lladhi ahyana ba'da ma amatana wa ilayhi-n-nushur","translation_es":"Alabado sea Allah, Quien nos ha dado vida después de habernos hecho morir (durante el sueño), y a Él es la resurrección.","translation_ar":"الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور.","translation_en":"All praise is for Allah, Who gave us life after having taken it from us (during sleep), and to Him is the resurrection.","source":"Bukhari 6314"},{"id":"a_wake_al_imran","title":"Los últimos 10 versos de Al-Imran","title_ar":"أواخر آل عمران العشر","title_en":"The last 10 verses of Al-Imran","arabic":"إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ...","transliteration":"Inna fi khalqi-s-samawati wal-ardi wa-khtilafi-l-layli wan-nahari la-ayatin li-uli-l-albab...","translation_es":"Los últimos 10 versos de la sura Al-Imran (desde el verso 190 al 200).","translation_ar":"العشر الأواخر من سورة آل عمران (من الآية 190 إلى 200).","translation_en":"The last 10 verses of Surah Al-Imran (verses 190 to 200).","source":"Bukhari 4569"},{"id":"a_wake_alhamdulillah_afiya","title":"Alhamdulillah por la salud","title_ar":"الحمد لله على العافية","title_en":"Alhamdulillah for good health","arabic":"الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ","transliteration":"Al-hamdu lillahi-lladhi 'afani fi jasadi, wa radda 'alayya ruhi, wa adhina li bi-dhikrih","translation_es":"Alabado sea Allah, Quien me ha dado salud en mi cuerpo, me devolvió mi alma y me permitió recordarle.","translation_ar":"الحمد لله الذي عافاني في جسدي، ورد علي روحي، وأذن لي بذكره.","translation_en":"All praise is for Allah, Who granted me health in my body, returned my soul to me, and allowed me to remember Him.","source":"Tirmidhi 3401"},{"id":"a_wake_siwak","title":"Al usar el siwak (o cepillo)","title_ar":"عند استعمال السواك","title_en":"When using the siwak (or toothbrush)","arabic":"الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ الطَّهُورَ عَلَى الْمُسْلِمِينَ نِعْمَةً","transliteration":"Al-hamdu lillahi-lladhi ja'ala-t-tahura 'ala-l-muslimina ni'mah","translation_es":"Alabado sea Allah, Quien hizo de la purificación una bendición para los musulmanes.","translation_ar":"الحمد لله الذي جعل الطهور على المسلمين نعمة.","translation_en":"All praise is for Allah, Who made purification a blessing upon the Muslims.","source":"Bukhari 245"},{"id":"a_wake_dua_bad_dream","title":"Al tener un mal sueño","title_ar":"عند رؤية حلم مزعج","title_en":"Upon having a bad dream","arabic":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ","transliteration":"A'udhu bi-kalimatillahi-t-tammati min ghadabihi wa 'iqabih, wa sharri 'ibadih, wa min hamazati-sh-shayatini wa an yahdurun","translation_es":"Me refugio en las Palabras perfectas de Allah de Su ira y castigo, del mal de Sus siervos, y de las incitaciones de los demonios y de su presencia.","translation_ar":"أعوذ بكلمات الله التامات من غضبه وعقابه، وشر عباده، ومن همزات الشياطين وأن يحضرون.","translation_en":"I seek refuge in the perfect Words of Allah from His anger and punishment, from the evil of His servants, and from the whispers of the devils and their presence.","source":"Muslim 2261"},{"id":"a_wake_asbahna","title":"Asbahna 'ala fitrat al-Islam","title_ar":"أصبحنا على فطرة الإسلام","title_en":"Asbahna 'ala fitrat al-Islam (We awake upon the fitrah of Islam)","arabic":"أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ","transliteration":"Asbahna 'ala fitrati-l-Islam, wa 'ala kalimati-l-ikhlas, wa 'ala dini nabiyyina Muhammad, wa 'ala millati abina Ibrahim hanifan musliman wa ma kana mina-l-mushrikin","translation_es":"Hemos amanecido sobre la fitrah del Islam, sobre la palabra de la sinceridad, sobre la religión de nuestro Profeta Muhammad ﷺ, y sobre la comunidad de nuestro padre Ibrahim, monoteísta, musulmán, y no de los que asocian.","translation_ar":"أصبحنا على فطرة الإسلام، وعلى كلمة الإخلاص، وعلى دين نبينا محمد ﷺ، وعلى ملة أبينا إبراهيم حنيفاً مسلماً وما كان من المشركين.","translation_en":"We have arisen upon the fitrah of Islam, upon the word of sincerity, upon the religion of our Prophet Muhammad ﷺ, and upon the creed of our father Ibrahim, upright, Muslim, and never among the polytheists.","source":"Ahmad 15367"},{"id":"a_wake_dua_khayr","title":"Súplica al abrir los ojos","title_ar":"دعاء عند فتح العينين","title_en":"Supplication upon opening the eyes","arabic":"اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ","transliteration":"Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namut, wa ilayka-n-nushur","translation_es":"¡Oh Allah! Contigo hemos amanecido, contigo anochecemos, contigo vivimos, contigo morimos, y a Ti es el retorno.","translation_ar":"اللهم بك أصبحنا، وبك أمسينا، وبك نحيا، وبك نموت، وإليك النشور.","translation_en":"O Allah! By You we enter the morning, by You we enter the evening, by You we live, by You we die, and to You is the resurrection.","source":"Tirmidhi 3391"},{"id":"h0","title":"Para la angustia","title_ar":"دعاء الهم والحزن","title_en":"Para la angustia","arabic":"اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي وَنُورَ صَدْرِي وَجَلَاءَ حُزْنِي وَذَهَابَ هَمِّي","transliteration":"","translation_es":"Oh Allah, haz que el Corán sea la primavera de mi corazón, la luz de mi pecho y el fin de mi tristeza.","translation_ar":"اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي وَنُورَ صَدْرِي وَجَلَاءَ حُزْنِي وَذَهَابَ هَمِّي","translation_en":"O Allah, make the Qur'an the spring of my heart, the light of my breast, and the dispeller of my sorrow.","source":"Ahmad 3712"},{"id":"h1","title":"En la aflicción","title_ar":"دعاء الكرب","title_en":"En la aflicción","arabic":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","transliteration":"","translation_es":"No hay divinidad sino Allah, el Inmenso, el Tolerante; Señor del Trono noble.","translation_ar":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","translation_en":"There is no god but Allah, the Mighty, the Forbearing; Lord of the heavens and the earth.","source":"Bujari 6345"},{"id":"h2","title":"Para el alivio","title_ar":"دعاء الفرج","title_en":"Para el alivio","arabic":"اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ","transliteration":"","translation_es":"Oh Allah, espero Tu misericordia; no me dejes a mí mismo ni un instante.","translation_ar":"اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ","translation_en":"O Allah, I hope for Your mercy; do not leave me to myself even for a blink.","source":"Abu Dawud 5090"},{"id":"h3","title":"Para la pena","title_ar":"دعاء الضيق","title_en":"Para la pena","arabic":"حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ","transliteration":"","translation_es":"Allah me basta, y Él es el mejor Protector.","translation_ar":"حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ","translation_en":"Allah is sufficient for me, and He is the best Disposer of affairs.","source":"Corán 3:173"},{"id":"h4","title":"Para decidir","title_ar":"الاستخارة","title_en":"Para decidir","arabic":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ","transliteration":"","translation_es":"Oh Allah, Te pido que elijas por mí con Tu conocimiento y me capacites con Tu poder.","translation_ar":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ","translation_en":"O Allah, I seek Your guidance by Your knowledge and Your power.","source":"Bujari 1166"},{"id":"h5","title":"Para la guía","title_ar":"دعاء الهداية","title_en":"Para la guía","arabic":"اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي","transliteration":"","translation_es":"Oh Allah, guíame y hazme firme en el camino recto.","translation_ar":"اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي","translation_en":"O Allah, guide me and keep me on the right path.","source":"Muslim 2725"},{"id":"h6","title":"Para la salud","title_ar":"دعاء العافية","title_en":"Para la salud","arabic":"اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ","transliteration":"","translation_es":"Oh Allah, sana mi cuerpo, mi oído y mi vista.","translation_ar":"اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ","translation_en":"O Allah, grant health to my body, my hearing and my sight.","source":"Abu Dawud 5090"},{"id":"h7","title":"Para la fortaleza","title_ar":"دعاء القوة","title_en":"Para la fortaleza","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ","transliteration":"","translation_es":"Oh Allah, me refugio en Ti de la incapacidad, la pereza, la cobardía y la avaricia.","translation_ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ","translation_en":"O Allah, I seek refuge in You from incapacity, laziness, cowardice and miserliness.","source":"Bujari 6369"},{"id":"h8","title":"Para el sustento","title_ar":"دعاء الرزق","title_en":"Para el sustento","arabic":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","transliteration":"","translation_es":"Oh Allah, hazme suficiente con lo lícito frente a lo ilícito.","translation_ar":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","translation_en":"O Allah, suffice me with what is lawful against what is unlawful.","source":"Tirmidhi 3563"},{"id":"h9","title":"Para la suficiencia","title_ar":"دعاء الغنى","title_en":"Para la suficiencia","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","transliteration":"","translation_es":"Oh Allah, Te pido guía, piedad, castidad y suficiencia.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","translation_en":"O Allah, I ask You for guidance, piety, chastity and contentment.","source":"Muslim 2721"},{"id":"h10","title":"Para las deudas","title_ar":"دعاء القرض","title_en":"Para las deudas","arabic":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ","transliteration":"","translation_es":"Oh Allah, líbrame de las deudas y enriquéceme con Tu gracia.","translation_ar":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ","translation_en":"O Allah, free me from debt and enrich me from Your bounty.","source":"Tirmidhi 3563"},{"id":"h11","title":"Para el enfermo","title_ar":"دعاء الشفاء","title_en":"Para el enfermo","arabic":"أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ","transliteration":"","translation_es":"Pido a Allah, el Inmenso, Señor del Trono, que te cure.","translation_ar":"أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ","translation_en":"I ask Allah, the Mighty, Lord of the Throne, to heal you.","source":"Tirmidhi 2083"},{"id":"h12","title":"Para el enfermo","title_ar":"دعاء المريض","title_en":"Para el enfermo","arabic":"اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَاسَ، اشْفِ أَنْتَ الشَّافِي","transliteration":"","translation_es":"Oh Allah, Señor de la gente, quita el mal; Tú eres el Sanador.","translation_ar":"اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَاسَ، اشْفِ أَنْتَ الشَّافِي","translation_en":"O Allah, Lord of mankind, remove the harm; You are the Healer.","source":"Bujari 5675"},{"id":"h13","title":"Para el desconsuelo","title_ar":"دعاء كشف الكرب","title_en":"Para el desconsuelo","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ فَرَجًا قَرِيبًا وَصَبْرًا جَمِيلًا","transliteration":"","translation_es":"Oh Allah, Te pido un alivio cercano y una hermosa paciencia.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ فَرَجًا قَرِيبًا وَصَبْرًا جَمِيلًا","translation_en":"O Allah, I ask You for near relief and beautiful patience.","source":"Athar"},{"id":"h14","title":"Para el éxito","title_ar":"دعاء التوفيق","title_en":"Para el éxito","arabic":"اللَّهُمَّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ","transliteration":"","translation_es":"Oh Allah, ayúdame y no ayudes contra mí; dame la victoria sin que sea contra mí.","translation_ar":"اللَّهُمَّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ","translation_en":"O Allah, help me and not against me; grant me victory and not over me.","source":"Tirmidhi 3551"},{"id":"h15","title":"Para la bendición","title_ar":"دعاء البركة","title_en":"Para la bendición","arabic":"اللَّهُمَّ بَارِكْ لِي فِيمَا رَزَقْتَنِي وَاخْلُفْ عَلَيَّ كُلَّ غَائِبَةٍ بِخَيْرٍ","transliteration":"","translation_es":"Oh Allah, bendice lo que me has dado y suple toda ausencia con bien.","translation_ar":"اللَّهُمَّ بَارِكْ لِي فِيمَا رَزَقْتَنِي وَاخْلُفْ عَلَيَّ كُلَّ غَائِبَةٍ بِخَيْرٍ","translation_en":"O Allah, bless what You have given me and replace every loss with good.","source":"Hisn al-Muslim"},{"id":"h16","title":"Para el conocimiento","title_ar":"دعاء العلم","title_en":"Para el conocimiento","arabic":"رَبِّ زِدْنِي عِلْمًا","transliteration":"","translation_es":"Señor, aumenta mi conocimiento.","translation_ar":"رَبِّ زِدْنِي عِلْمًا","translation_en":"My Lord, increase me in knowledge.","source":"Corán 20:114"},{"id":"h17","title":"Para la comprensión","title_ar":"دعاء الفهم","title_en":"Para la comprensión","arabic":"رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي","transliteration":"","translation_es":"Señor, expande mi pecho, facilita mi tarea y suelta el nudo de mi lengua.","translation_ar":"رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي","translation_en":"My Lord, expand my chest, ease my task and untie the knot from my tongue.","source":"Corán 20:25-27"},{"id":"h18","title":"Para la firmeza","title_ar":"دعاء الثبات","title_en":"Para la firmeza","arabic":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ","transliteration":"","translation_es":"Oh Cambiador de los corazones, afirma mi corazón en Tu religión.","translation_ar":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ","translation_en":"O Turner of hearts, make my heart firm upon Your religion.","source":"Tirmidhi 2140"},{"id":"h19","title":"Para el perdón","title_ar":"دعاء الاستغفار","title_en":"Para el perdón","arabic":"أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","transliteration":"","translation_es":"Pido perdón a Allah, el Viviente, el Eterno, y a Él me vuelvo.","translation_ar":"أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","translation_en":"I seek forgiveness from Allah, the Ever-Living, and I repent to Him.","source":"Abu Dawud 1517"},{"id":"h20","title":"La mejor súplica de perdón","title_ar":"سيد الاستغفار","title_en":"La mejor súplica de perdón","arabic":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ","transliteration":"","translation_es":"Oh Allah, Tú eres mi Señor, me creaste y soy Tu siervo; cumplo Tu pacto cuanto puedo.","translation_ar":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ","translation_en":"O Allah, You are my Lord; You created me and I am Your servant, keeping Your covenant as I am able.","source":"Bujari 6306"},{"id":"h21","title":"Para el arrepentimiento","title_ar":"دعاء التوبة","title_en":"Para el arrepentimiento","arabic":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ","transliteration":"","translation_es":"Señor, perdóname y acepta mi arrepentimiento; Tú eres el Indulgente.","translation_ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ","translation_en":"My Lord, forgive me and accept my repentance; You are the Accepter of repentance.","source":"Tirmidhi 3434"},{"id":"h22","title":"Para el pecado","title_ar":"دعاء الذنب","title_en":"Para el pecado","arabic":"اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","transliteration":"","translation_es":"Oh Allah, he sido injusto conmigo mismo; nadie perdona los pecados sino Tú.","translation_ar":"اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","translation_en":"O Allah, I have wronged myself greatly, and none forgives sins but You.","source":"Bujari 834"},{"id":"h23","title":"Para la misericordia","title_ar":"دعاء الرحمة","title_en":"Para la misericordia","arabic":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً","transliteration":"","translation_es":"Señor, no desvíes nuestros corazones después de habernos guiado.","translation_ar":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً","translation_en":"Our Lord, do not let our hearts deviate after You have guided us.","source":"Corán 3:8"},{"id":"h24","title":"Para ambos mundos","title_ar":"دعاء الدنيا والآخرة","title_en":"Para ambos mundos","arabic":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","transliteration":"","translation_es":"Señor, danos bien en este mundo y en el otro, y protégenos del fuego.","translation_ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","translation_en":"Our Lord, give us good in this world and the next, and protect us from the Fire.","source":"Corán 2:201"},{"id":"h25","title":"Por los padres","title_ar":"دعاء الوالدين","title_en":"Por los padres","arabic":"رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","transliteration":"","translation_es":"Señor, ten misericordia de ellos como me criaron siendo niño.","translation_ar":"رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","translation_en":"My Lord, have mercy on them as they raised me when I was small.","source":"Corán 17:24"},{"id":"h26","title":"Por la descendencia","title_ar":"دعاء الذرية","title_en":"Por la descendencia","arabic":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا","transliteration":"","translation_es":"Señor, danos en nuestras parejas e hijos consuelo, y haznos guías de los piadosos.","translation_ar":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا","translation_en":"Our Lord, grant us joy in our spouses and children, and make us leaders of the righteous.","source":"Corán 25:74"},{"id":"h27","title":"Por un hijo virtuoso","title_ar":"دعاء الولد الصالح","title_en":"Por un hijo virtuoso","arabic":"رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ","transliteration":"","translation_es":"Señor, concédeme un hijo entre los justos.","translation_ar":"رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ","translation_en":"My Lord, grant me a righteous child.","source":"Corán 37:100"},{"id":"h28","title":"Por un buen cónyuge","title_ar":"دعاء الزوجة الصالحة","title_en":"Por un buen cónyuge","arabic":"رَبَّنَا هَبْ لَنَا مِنْ لَدُنْكَ زَوْجًا صَالِحًا","transliteration":"","translation_es":"Señor, concédenos de Ti un cónyuge virtuoso.","translation_ar":"رَبَّنَا هَبْ لَنَا مِنْ لَدُنْكَ زَوْجًا صَالِحًا","translation_en":"Our Lord, grant us from Yourself a righteous spouse.","source":"Dua"},{"id":"h29","title":"Para la rectitud","title_ar":"دعاء السداد","title_en":"Para la rectitud","arabic":"رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا","transliteration":"","translation_es":"Señor, danos misericordia de Ti y dispón nuestra empresa con rectitud.","translation_ar":"رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا","translation_en":"Our Lord, grant us mercy from Yourself and guide our affair rightly.","source":"Corán 18:10"},{"id":"h30","title":"Para la ayuda","title_ar":"دعاء العون","title_en":"Para la ayuda","arabic":"رَبِّ اشْرَحْ لِي صَدْرِي","transliteration":"","translation_es":"Señor, expande mi pecho.","translation_ar":"رَبِّ اشْرَحْ لِي صَدْرِي","translation_en":"My Lord, expand my chest.","source":"Corán 20:25"},{"id":"h31","title":"Contra el deseo","title_ar":"دعاء الانتصار على النفس","title_en":"Contra el deseo","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ","transliteration":"","translation_es":"Oh Allah, me refugio en Ti del mal de mi alma y del mal de Satanás.","translation_ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ","translation_en":"O Allah, I seek refuge in You from the evil of my soul and of Satan.","source":"Abu Dawud 5068"},{"id":"h32","title":"Al entrar en casa","title_ar":"دعاء دخول البيت","title_en":"Al entrar en casa","arabic":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","transliteration":"","translation_es":"En el nombre de Allah entramos y salimos, y en nuestro Señor confiamos.","translation_ar":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","translation_en":"In Allah's name we enter and leave, and in our Lord we trust.","source":"Abu Dawud 5096"},{"id":"h33","title":"Al salir","title_ar":"دعاء الخروج","title_en":"Al salir","arabic":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","transliteration":"","translation_es":"En el nombre de Allah, confío en Allah; no hay fuerza sino con Allah.","translation_ar":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","translation_en":"In Allah's name, I trust in Allah; there is no power but with Allah.","source":"Abu Dawud 5095"},{"id":"h34","title":"Para el viaje","title_ar":"دعاء السفر","title_en":"Para el viaje","arabic":"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ","transliteration":"","translation_es":"Gloria a Quien puso esto a nuestro servicio; a nuestro Señor volvemos.","translation_ar":"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ","translation_en":"Glory to Him who subjected this to us; to our Lord we shall return.","source":"Corán 43:13-14"},{"id":"h35","title":"Antes de comer","title_ar":"دعاء الطعام","title_en":"Antes de comer","arabic":"بِسْمِ اللَّهِ وَعَلَى بَرَكَةِ اللَّهِ","transliteration":"","translation_es":"En el nombre de Allah y con Su bendición.","translation_ar":"بِسْمِ اللَّهِ وَعَلَى بَرَكَةِ اللَّهِ","translation_en":"In the name of Allah and with His blessing.","source":"Hisn al-Muslim"},{"id":"h36","title":"Tras comer","title_ar":"دعاء بعد الطعام","title_en":"Tras comer","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ","transliteration":"","translation_es":"Alabado sea Allah que nos dio de comer y beber y nos hizo musulmanes.","translation_ar":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ","translation_en":"Praise be to Allah who fed us, gave us drink and made us Muslims.","source":"Tirmidhi 3457"},{"id":"h37","title":"Antes de dormir","title_ar":"دعاء النوم","title_en":"Antes de dormir","arabic":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","transliteration":"","translation_es":"En Tu nombre, oh Allah, muero y vivo.","translation_ar":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","translation_en":"In Your name, O Allah, I die and I live.","source":"Bujari 6324"},{"id":"h38","title":"Al despertar","title_ar":"دعاء الاستيقاظ","title_en":"Al despertar","arabic":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","transliteration":"","translation_es":"Alabado sea Allah que nos dio vida después de la muerte; a Él es el retorno.","translation_ar":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","translation_en":"Praise be to Allah who gave us life after death; to Him is the return.","source":"Bujari 6312"},{"id":"h39","title":"Para la lluvia","title_ar":"دعاء المطر","title_en":"Para la lluvia","arabic":"اللَّهُمَّ صَيِّبًا نَافِعًا","transliteration":"","translation_es":"Oh Allah, una lluvia beneficiosa.","translation_ar":"اللَّهُمَّ صَيِّبًا نَافِعًا","translation_en":"O Allah, a beneficial rain.","source":"Bujari 1032"},{"id":"h40","title":"Con el viento","title_ar":"دعاء عند الريح","title_en":"Con el viento","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَأَعُوذُ بِكَ مِنْ شَرِّهَا","transliteration":"","translation_es":"Oh Allah, Te pido su bien y me refugio de su mal.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَأَعُوذُ بِكَ مِنْ شَرِّهَا","translation_en":"O Allah, I ask You for its good and seek refuge from its evil.","source":"Abu Dawud 5099"},{"id":"h41","title":"Al entrar en la mezquita","title_ar":"دعاء الدخول للمسجد","title_en":"Al entrar en la mezquita","arabic":"اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","transliteration":"","translation_es":"Oh Allah, ábreme las puertas de Tu misericordia.","translation_ar":"اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","translation_en":"O Allah, open for me the gates of Your mercy.","source":"Muslim 713"},{"id":"h42","title":"Al salir de la mezquita","title_ar":"دعاء الخروج من المسجد","title_en":"Al salir de la mezquita","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","transliteration":"","translation_es":"Oh Allah, Te pido de Tu favor.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","translation_en":"O Allah, I ask You of Your bounty.","source":"Muslim 713"},{"id":"h43","title":"Tras el wudu","title_ar":"دعاء الوضوء","title_en":"Tras el wudu","arabic":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","transliteration":"","translation_es":"Testifico que no hay divinidad sino Allah y que Muhammad es Su siervo y mensajero.","translation_ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","translation_en":"I bear witness that there is no god but Allah and Muhammad is His servant and messenger.","source":"Muslim 234"},{"id":"h44","title":"Tras el adhan","title_ar":"دعاء الأذان","title_en":"Tras el adhan","arabic":"اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ","transliteration":"","translation_es":"Oh Allah, Señor de esta llamada perfecta, concede a Muhammad la intercesión y la excelencia.","translation_ar":"اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ","translation_en":"O Allah, Lord of this perfect call, grant Muhammad the intercession and favour.","source":"Bujari 614"},{"id":"h45","title":"Para la angustia","title_ar":"دعاء القنوت","title_en":"Para la angustia","arabic":"اللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنُؤْمِنُ بِكَ وَنَتَوَكَّلُ عَلَيْكَ","transliteration":"","translation_es":"Oh Allah, buscamos Tu ayuda, Tu perdón, creemos en Ti y en Ti confiamos.","translation_ar":"اللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنُؤْمِنُ بِكَ وَنَتَوَكَّلُ عَلَيْكَ","translation_en":"O Allah, we seek Your help and forgiveness, believe in You and rely on You.","source":"Tirmidhi 464"},{"id":"h46","title":"Al terminar el Corán","title_ar":"دعاء ختم القرآن","title_en":"Al terminar el Corán","arabic":"اللَّهُمَّ ارْحَمْنِي بِالْقُرْآنِ وَاجْعَلْهُ لِي إِمَامًا وَنُورًا وَهُدًى وَرَحْمَةً","transliteration":"","translation_es":"Oh Allah, ten misericordia de mí por el Corán; hazlo guía, luz y misericordia.","translation_ar":"اللَّهُمَّ ارْحَمْنِي بِالْقُرْآنِ وَاجْعَلْهُ لِي إِمَامًا وَنُورًا وَهُدًى وَرَحْمَةً","translation_en":"O Allah, have mercy on me through the Qur'an; make it a guide, light and mercy.","source":"Tirmidhi 2905"},{"id":"h47","title":"Para agradecer","title_ar":"دعاء الشكر","title_en":"Para agradecer","arabic":"اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","transliteration":"","translation_es":"Oh Allah, ayúdame a recordarte, agradecerte y adorarte bien.","translation_ar":"اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","translation_en":"O Allah, help me remember You, thank You and worship You well.","source":"Abu Dawud 1522"},{"id":"h48","title":"Para alabarte","title_ar":"دعاء الثناء","title_en":"Para alabarte","arabic":"اللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ، وَلَكَ الْمُلْكُ كُلُّهُ، بِيَدِكَ الْخَيْرُ كُلُّهُ","transliteration":"","translation_es":"Oh Allah, Túya es toda alabanza y todo dominio; en Tu mano está todo bien.","translation_ar":"اللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ، وَلَكَ الْمُلْكُ كُلُّهُ، بِيَدِكَ الْخَيْرُ كُلُّهُ","translation_en":"O Allah, Yours is all praise and all dominion; in Your hand is all good.","source":"Hisn al-Muslim"},{"id":"h49","title":"Para el perdón en la noche","title_ar":"دعاء العفو","title_en":"Para el perdón en la noche","arabic":"اللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","transliteration":"","translation_es":"Oh Allah, Tú eres Indulgente y Generoso; perdóname.","translation_ar":"اللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","translation_en":"O Allah, You are Forgiving and Generous; forgive me.","source":"Tirmidhi 3513"},{"id":"h50","title":"En la noche del decreto","title_ar":"دعاء ليلة القدر","title_en":"En la noche del decreto","arabic":"اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","transliteration":"","translation_es":"Oh Allah, Tú eres Indulgente y amas perdonar; perdóname.","translation_ar":"اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","translation_en":"O Allah, You are Forgiving and love forgiveness; forgive me.","source":"Tirmidhi 3513"},{"id":"h51","title":"Al recibir un bien","title_ar":"دعاء الحمد","title_en":"Al recibir un bien","arabic":"الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ","transliteration":"","translation_es":"Alabado sea Allah por cuya gracia se completan las buenas obras.","translation_ar":"الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ","translation_en":"Praise be to Allah by whose grace good deeds are completed.","source":"Ibn Majah 3803"},{"id":"h52","title":"Ante la desgracia","title_ar":"دعاء عند المصيبة","title_en":"Ante la desgracia","arabic":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا","transliteration":"","translation_es":"A Allah pertenecemos y a Él volvemos; recompénsame y sustitúyelo por algo mejor.","translation_ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا","translation_en":"To Allah we belong and to Him we return; reward me and replace it with better.","source":"Muslim 918"},{"id":"h53","title":"Para la aceptación","title_ar":"دعاء الرضا","title_en":"Para la aceptación","arabic":"اللَّهُمَّ رَضِّنِي بِمَا قَسَمْتَ لِي وَبَارِكْ لِي فِيهِ","transliteration":"","translation_es":"Oh Allah, hazme aceptar lo que me has repartido y bendícelo.","translation_ar":"اللَّهُمَّ رَضِّنِي بِمَا قَسَمْتَ لِي وَبَارِكْ لِي فِيهِ","translation_en":"O Allah, make me content with what You have apportioned for me.","source":"Hisn al-Muslim"},{"id":"h54","title":"Contra la ansiedad","title_ar":"دعاء القلق","title_en":"Contra la ansiedad","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ","transliteration":"","translation_es":"Oh Allah, me refugio en Ti de la preocupación, la tristeza, la incapacidad y la pereza.","translation_ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ","translation_en":"O Allah, I seek refuge in You from worry, sadness, incapacity and laziness.","source":"Bujari 6363"},{"id":"h55","title":"Contra el miedo","title_ar":"دعاء الخوف","title_en":"Contra el miedo","arabic":"اللَّهُمَّ اسْتُرْ عَوْرَاتِنَا وَآمِنْ رَوْعَاتِنَا","transliteration":"","translation_es":"Oh Allah, cubre nuestras faltas y calma nuestros miedos.","translation_ar":"اللَّهُمَّ اسْتُرْ عَوْرَاتِنَا وَآمِنْ رَوْعَاتِنَا","translation_en":"O Allah, cover our faults and calm our fears.","source":"Abu Dawud 1531"},{"id":"h56","title":"Para la victoria","title_ar":"دعاء النصر","title_en":"Para la victoria","arabic":"اللَّهُمَّ انْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","transliteration":"","translation_es":"Oh Allah, danos la victoria sobre el pueblo incrédulo.","translation_ar":"اللَّهُمَّ انْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","translation_en":"O Allah, grant us victory over the disbelieving people.","source":"Corán 2:286"},{"id":"h57","title":"Para la dignidad","title_ar":"دعاء العزة","title_en":"Para la dignidad","arabic":"اللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ","transliteration":"","translation_es":"Oh Allah, honra el Islam y a los musulmanes.","translation_ar":"اللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَالْمُسْلِمِينَ","translation_en":"O Allah, honour Islam and the Muslims.","source":"Dua"},{"id":"h58","title":"Por los musulmanes","title_ar":"دعاء للمسلمين","title_en":"Por los musulmanes","arabic":"اللَّهُمَّ اغْفِرْ لِلْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ","transliteration":"","translation_es":"Oh Allah, perdona a los musulmanes y musulmanas, creyentes hombres y mujeres.","translation_ar":"اللَّهُمَّ اغْفِرْ لِلْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ","translation_en":"O Allah, forgive the Muslim men and women, believing men and women.","source":"Tirmidhi 3590"},{"id":"h59","title":"Por la comunidad","title_ar":"دعاء للأمة","title_en":"Por la comunidad","arabic":"اللَّهُمَّ أَصْلِحْ أُمَّةَ مُحَمَّدٍ","transliteration":"","translation_es":"Oh Allah, corrige la comunidad de Muhammad.","translation_ar":"اللَّهُمَّ أَصْلِحْ أُمَّةَ مُحَمَّدٍ","translation_en":"O Allah, set right the community of Muhammad.","source":"Dua"},{"id":"h60","title":"Para la piedad","title_ar":"دعاء البر","title_en":"Para la piedad","arabic":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي","transliteration":"","translation_es":"Señor, hazme constante en la oración, y a mi descendencia.","translation_ar":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي","translation_en":"My Lord, make me steadfast in prayer, and my descendants.","source":"Corán 14:40"},{"id":"h61","title":"Para la aceptación","title_ar":"دعاء القبول","title_en":"Para la aceptación","arabic":"رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ","transliteration":"","translation_es":"Señor, acéptalo de nosotros; Tú eres el Oyente, el Sabio.","translation_ar":"رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ","translation_en":"Our Lord, accept it from us; You are the All-Hearing, the All-Knowing.","source":"Corán 2:127"},{"id":"h62","title":"Para la paciencia","title_ar":"دعاء الصبر","title_en":"Para la paciencia","arabic":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا","transliteration":"","translation_es":"Señor, derrama sobre nosotros paciencia y afirma nuestros pasos.","translation_ar":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا","translation_en":"Our Lord, pour patience upon us and make our feet firm.","source":"Corán 2:250"},{"id":"h63","title":"Para la luz","title_ar":"دعاء النور","title_en":"Para la luz","arabic":"رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا","transliteration":"","translation_es":"Señor, completa nuestra luz y perdónanos.","translation_ar":"رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا","translation_en":"Our Lord, perfect our light for us and forgive us.","source":"Corán 66:8"},{"id":"h64","title":"Para la confianza","title_ar":"دعاء التوكل","title_en":"Para la confianza","arabic":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ","transliteration":"","translation_es":"Allah nos basta; Él es el mejor Protector.","translation_ar":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ","translation_en":"Allah is sufficient for us; He is the best Disposer of affairs.","source":"Corán 3:173"},{"id":"h65","title":"Para la certeza","title_ar":"دعاء اليقين","title_en":"Para la certeza","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ وَيَقِينًا لَا يَنْفَدُ","transliteration":"","translation_es":"Oh Allah, Te pido una fe que no retroceda y una certeza que no se agote.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ وَيَقِينًا لَا يَنْفَدُ","translation_en":"O Allah, I ask You for faith that does not waver and certainty that does not fade.","source":"Dua"},{"id":"h66","title":"Para un corazón sano","title_ar":"دعاء القلب السليم","title_en":"Para un corazón sano","arabic":"اللَّهُمَّ طَهِّرْ قَلْبِي مِنَ النِّفَاقِ وَعَمَلِي مِنَ الرِّيَاءِ","transliteration":"","translation_es":"Oh Allah, purifica mi corazón de la hipocresía y mi obra de la ostentación.","translation_ar":"اللَّهُمَّ طَهِّرْ قَلْبِي مِنَ النِّفَاقِ وَعَمَلِي مِنَ الرِّيَاءِ","translation_en":"O Allah, purify my heart from hypocrisy and my deeds from showing off.","source":"Dua"},{"id":"h67","title":"Para el buen carácter","title_ar":"دعاء حسن الخلق","title_en":"Para el buen carácter","arabic":"اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ","transliteration":"","translation_es":"Oh Allah, guíame a los mejores modales.","translation_ar":"اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ","translation_en":"O Allah, guide me to the best of manners.","source":"Muslim 771"},{"id":"h68","title":"Para la castidad","title_ar":"دعاء العفة","title_en":"Para la castidad","arabic":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَوَاحِشِ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ","transliteration":"","translation_es":"Oh Allah, me refugio de las indecencias, visibles y ocultas.","translation_ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَوَاحِشِ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ","translation_en":"O Allah, I seek refuge from indecencies, open or hidden.","source":"Abu Dawud 1552"},{"id":"h69","title":"Para un buen final","title_ar":"دعاء حسن الخاتمة","title_en":"Para un buen final","arabic":"اللَّهُمَّ اجْعَلْ خَيْرَ عُمُرِي آخِرَهُ وَخَيْرَ عَمَلِي خَاتِمَتَهُ","transliteration":"","translation_es":"Oh Allah, haz lo mejor de mi vida su final y lo mejor de mis obras su conclusión.","translation_ar":"اللَّهُمَّ اجْعَلْ خَيْرَ عُمُرِي آخِرَهُ وَخَيْرَ عَمَلِي خَاتِمَتَهُ","translation_en":"O Allah, make the best of my life its end and the best of my deeds its conclusion.","source":"Dua"},{"id":"h70","title":"Para el tiempo","title_ar":"دعاء البركة في الوقت","title_en":"Para el tiempo","arabic":"اللَّهُمَّ بَارِكْ لِي فِي وَقْتِي وَعَمَلِي","transliteration":"","translation_es":"Oh Allah, bendice mi tiempo y mi obra.","translation_ar":"اللَّهُمَّ بَارِكْ لِي فِي وَقْتِي وَعَمَلِي","translation_en":"O Allah, bless my time and my work.","source":"Dua"},{"id":"h71","title":"Para la calma","title_ar":"دعاء السكينة","title_en":"Para la calma","arabic":"اللَّهُمَّ أَنْزِلْ عَلَيْنَا سَكِينَتَكَ","transliteration":"","translation_es":"Oh Allah, haz descender sobre nosotros Tu sosiego.","translation_ar":"اللَّهُمَّ أَنْزِلْ عَلَيْنَا سَكِينَتَكَ","translation_en":"O Allah, send down Your tranquillity upon us.","source":"Corán 48:18"},{"id":"h72","title":"Para conservar la bendición","title_ar":"دعاء حفظ النعمة","title_en":"Para conservar la bendición","arabic":"اللَّهُمَّ لَا تَسْلُبْنِي نِعْمَتَكَ","transliteration":"","translation_es":"Oh Allah, no me quites Tu bendición.","translation_ar":"اللَّهُمَّ لَا تَسْلُبْنِي نِعْمَتَكَ","translation_en":"O Allah, do not take away Your blessing from me.","source":"Dua"},{"id":"h73","title":"Para la salud","title_ar":"دعاء الصحة والعافية","title_en":"Para la salud","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الصِّحَّةَ وَالْعَافِيَةَ","transliteration":"","translation_es":"Oh Allah, Te pido salud y bienestar.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الصِّحَّةَ وَالْعَافِيَةَ","translation_en":"O Allah, I ask You for health and well-being.","source":"Dua"},{"id":"h74","title":"Por la salud de los padres","title_ar":"دعاء الشفاء للوالدين","title_en":"Por la salud de los padres","arabic":"اللَّهُمَّ اشْفِ وَالِدَيَّ شِفَاءً لَا يُغَادِرُ سَقَمًا","transliteration":"","translation_es":"Oh Allah, cura a mis padres con una curación que no deje enfermedad.","translation_ar":"اللَّهُمَّ اشْفِ وَالِدَيَّ شِفَاءً لَا يُغَادِرُ سَقَمًا","translation_en":"O Allah, heal my parents with a healing that leaves no illness.","source":"Dua"},{"id":"h75","title":"Para el Paraíso","title_ar":"دعاء الجنة","title_en":"Para el Paraíso","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ","transliteration":"","translation_es":"Oh Allah, Te pido el Paraíso y me refugio del Fuego.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ","translation_en":"O Allah, I ask You for Paradise and seek refuge from the Fire.","source":"Abu Dawud 792"},{"id":"h76","title":"Para ver a Allah","title_ar":"دعاء الرؤية","title_en":"Para ver a Allah","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ","transliteration":"","translation_es":"Oh Allah, Te pido el placer de contemplar Tu rostro.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ","translation_en":"O Allah, I ask You for the joy of gazing upon Your face.","source":"Nasa'i 1305"},{"id":"h77","title":"Para que se acepte la obra","title_ar":"دعاء القبول في العمل","title_en":"Para que se acepte la obra","arabic":"رَبَّنَا تَقَبَّلْ مِنَّا","transliteration":"","translation_es":"Señor, acéptalo de nosotros.","translation_ar":"رَبَّنَا تَقَبَّلْ مِنَّا","translation_en":"Our Lord, accept it from us.","source":"Corán 2:127"},{"id":"h78","title":"Para la serenidad","title_ar":"دعاء الطمأنينة","title_en":"Para la serenidad","arabic":"رَبَّنَا أَنْزِلْ عَلَيْنَا مَائِدَةً مِنَ السَّمَاءِ","transliteration":"","translation_es":"Señor, haznos descender una mesa del cielo.","translation_ar":"رَبَّنَا أَنْزِلْ عَلَيْنَا مَائِدَةً مِنَ السَّمَاءِ","translation_en":"Our Lord, send down to us a table from heaven.","source":"Corán 5:114"},{"id":"h79","title":"Para la sabiduría","title_ar":"دعاء الحكمة","title_en":"Para la sabiduría","arabic":"رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","transliteration":"","translation_es":"Señor, concédeme sabiduría y úneme a los justos.","translation_ar":"رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","translation_en":"My Lord, grant me wisdom and join me with the righteous.","source":"Corán 26:83"},{"id":"h80","title":"Para la veracidad","title_ar":"دعاء الصدق","title_en":"Para la veracidad","arabic":"رَبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ","transliteration":"","translation_es":"Señor, haz que entre y salga con verdad.","translation_ar":"رَبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ","translation_en":"My Lord, cause me to enter with truth and exit with truth.","source":"Corán 17:80"},{"id":"h81","title":"Para obrar bien","title_ar":"دعاء الشكر والعمل","title_en":"Para obrar bien","arabic":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ","transliteration":"","translation_es":"Señor, inspírame a agradecer Tu gracia que me concediste.","translation_ar":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ","translation_en":"My Lord, inspire me to be thankful for Your favour.","source":"Corán 46:15"},{"id":"h82","title":"Para facilitar","title_ar":"دعاء التيسير","title_en":"Para facilitar","arabic":"اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا","transliteration":"","translation_es":"Oh Allah, nada es fácil sino lo que Tú haces fácil.","translation_ar":"اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا","translation_en":"O Allah, nothing is easy except what You make easy.","source":"Ibn Hibban 2427"},{"id":"h83","title":"Para la preocupación","title_ar":"دعاء كفاية الهم","title_en":"Para la preocupación","arabic":"اللَّهُمَّ اكْفِنِي هَمِّي","transliteration":"","translation_es":"Oh Allah, basta para mi preocupación.","translation_ar":"اللَّهُمَّ اكْفِنِي هَمِّي","translation_en":"O Allah, suffice me in my worry.","source":"Dua"},{"id":"h84","title":"Para la discreción","title_ar":"دعاء الستر","title_en":"Para la discreción","arabic":"اللَّهُمَّ اسْتُرْنِي بِسِتْرِكَ الْجَمِيلِ","transliteration":"","translation_es":"Oh Allah, cúbreme con Tu hermoso velo.","translation_ar":"اللَّهُمَّ اسْتُرْنِي بِسِتْرِكَ الْجَمِيلِ","translation_en":"O Allah, cover me with Your beautiful concealment.","source":"Dua"},{"id":"h85","title":"Para sustento lícito","title_ar":"دعاء الرزق الحلال","title_en":"Para sustento lícito","arabic":"اللَّهُمَّ ارْزُقْنِي رِزْقًا حَلَالًا طَيِّبًا","transliteration":"","translation_es":"Oh Allah, concédeme un sustento lícito y bueno.","translation_ar":"اللَّهُمَّ ارْزُقْنِي رِزْقًا حَلَالًا طَيِّبًا","translation_en":"O Allah, grant me lawful and good provision.","source":"Dua"},{"id":"h86","title":"Para el hogar","title_ar":"دعاء البركة في البيت","title_en":"Para el hogar","arabic":"اللَّهُمَّ بَارِكْ لَنَا فِي بَيْتِنَا","transliteration":"","translation_es":"Oh Allah, bendice nuestro hogar.","translation_ar":"اللَّهُمَّ بَارِكْ لَنَا فِي بَيْتِنَا","translation_en":"O Allah, bless our home.","source":"Dua"},{"id":"h87","title":"Para hijos virtuosos","title_ar":"دعاء الأولاد بالصلاح","title_en":"Para hijos virtuosos","arabic":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ","transliteration":"","translation_es":"Señor, hazme constante en la oración.","translation_ar":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ","translation_en":"My Lord, make me steadfast in prayer.","source":"Corán 14:40"},{"id":"h88","title":"Para el éxito","title_ar":"دعاء النجاح","title_en":"Para el éxito","arabic":"رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ","transliteration":"","translation_es":"Señor, concédenos lo que prometiste a través de Tus mensajeros.","translation_ar":"رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ","translation_en":"Our Lord, grant us what You promised through Your messengers.","source":"Corán 3:194"},{"id":"h89","title":"Ante la necesidad","title_ar":"دعاء الفقر والغنى","title_en":"Ante la necesidad","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ","transliteration":"","translation_es":"Oh Allah, Te pido de Tu favor y Tu misericordia.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ","translation_en":"O Allah, I ask You of Your bounty and mercy.","source":"Dua"},{"id":"h90","title":"Para todo el bien","title_ar":"دعاء الخير كله","title_en":"Para todo el bien","arabic":"اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا","transliteration":"","translation_es":"Oh Allah, concede a mi alma su piedad y purifícala; Tú eres el mejor purificador.","translation_ar":"اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا","translation_en":"O Allah, grant my soul its piety and purify it; You are the best purifier.","source":"Muslim 2028"},{"id":"h91","title":"Para la seguridad","title_ar":"دعاء الأمان","title_en":"Para la seguridad","arabic":"اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي","transliteration":"","translation_es":"Oh Allah, guárdame delante y detrás de mí.","translation_ar":"اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي","translation_en":"O Allah, protect me from before and behind me.","source":"Abu Dawud 5074"},{"id":"h92","title":"Para la respuesta","title_ar":"دعاء الاستجابة","title_en":"Para la respuesta","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّكَ أَنْتَ اللَّهُ الْأَحَدُ الصَّمَدُ","transliteration":"","translation_es":"Oh Allah, Te pido por ser Tú Allah, el Único, el Eterno.","translation_ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّكَ أَنْتَ اللَّهُ الْأَحَدُ الصَّمَدُ","translation_en":"O Allah, I ask You by Your being Allah, the One, the Self-Sufficient.","source":"Abu Dawud 1493"},{"id":"h93","title":"Para la creación","title_ar":"دعاء للخلق","title_en":"Para la creación","arabic":"اللَّهُمَّ ارْحَمِ النَّاسَ جَمِيعًا","transliteration":"","translation_es":"Oh Allah, ten misericordia de toda la gente.","translation_ar":"اللَّهُمَّ ارْحَمِ النَّاسَ جَمِيعًا","translation_en":"O Allah, have mercy on all people.","source":"Dua"},{"id":"h94","title":"Para las intenciones","title_ar":"دعاء النوايا","title_en":"Para las intenciones","arabic":"اللَّهُمَّ طَهِّرْ نِيَّتِي","transliteration":"","translation_es":"Oh Allah, purifica mi intención.","translation_ar":"اللَّهُمَّ طَهِّرْ نِيَّتِي","translation_en":"O Allah, purify my intention.","source":"Dua"},{"id":"h95","title":"Para la complacencia","title_ar":"دعاء القبول والرضا","title_en":"Para la complacencia","arabic":"اللَّهُمَّ ارْضَ عَنِّي","transliteration":"","translation_es":"Oh Allah, complácete conmigo.","translation_ar":"اللَّهُمَّ ارْضَ عَنِّي","translation_en":"O Allah, be pleased with me.","source":"Dua"},{"id":"h96","title":"Para la unión","title_ar":"دعاء الصلة","title_en":"Para la unión","arabic":"اللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا","transliteration":"","translation_es":"Oh Allah, une nuestros corazones.","translation_ar":"اللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا","translation_en":"O Allah, bring our hearts together.","source":"Dua"},{"id":"h97","title":"Para la suficiencia","title_ar":"دعاء الكفاية","title_en":"Para la suficiencia","arabic":"اللَّهُمَّ اكْفِنَا كُلَّ شَيْءٍ","transliteration":"","translation_es":"Oh Allah, sálvanos de todo.","translation_ar":"اللَّهُمَّ اكْفِنَا كُلَّ شَيْءٍ","translation_en":"O Allah, suffice us in everything.","source":"Dua"},{"id":"h98","title":"Para la oración","title_ar":"دعاء الثبات على الصلاة","title_en":"Para la oración","arabic":"اللَّهُمَّ اجْعَلْنِي مِنَ الْمُقِيمِينَ الصَّلَاةَ","transliteration":"","translation_es":"Oh Allah, hazme de los constantes en la oración.","translation_ar":"اللَّهُمَّ اجْعَلْنِي مِنَ الْمُقِيمِينَ الصَّلَاةَ","translation_en":"O Allah, make me among those steadfast in prayer.","source":"Dua"},{"id":"h99","title":"Para la guía del camino","title_ar":"دعاء الهدى","title_en":"Para la guía del camino","arabic":"اللَّهُمَّ اهْدِنَا سَبِيلَ الرَّشَادِ","transliteration":"","translation_es":"Oh Allah, guíanos al camino de la rectitud.","translation_ar":"اللَّهُمَّ اهْدِنَا سَبِيلَ الرَّشَادِ","translation_en":"O Allah, guide us to the path of right guidance.","source":"Dua"},{"id":"h100","title":"Para la humildad","title_ar":"دعاء الذل لله","title_en":"Para la humildad","arabic":"اللَّهُمَّ اجْعَلْنَا مِنَ الْمُتَوَاضِعِينَ لَكَ","transliteration":"","translation_es":"Oh Allah, haznos de los humildes ante Ti.","translation_ar":"اللَّهُمَّ اجْعَلْنَا مِنَ الْمُتَوَاضِعِينَ لَكَ","translation_en":"O Allah, make us among the humble before You.","source":"Dua"}].filter(d=>d.arabic);
